def _title_decision_matches_url(decision: Optional[Dict[str, Any]], url: str = "") -> bool:
    if not isinstance(decision, dict) or not decision:
        return True
    decision_url = str(decision.get("url") or "").strip()
    current_url = str(url or "").strip()
    if not decision_url or not current_url:
        return True
    try:
        decision_key = canonicalize_url_for_dedup(decision_url) or decision_url
        current_key = canonicalize_url_for_dedup(current_url) or current_url
    except Exception:
        decision_key = decision_url
        current_key = current_url
    return decision_key == current_key


def _current_title_decision_for_url(owner: Any, url: str = "") -> Dict[str, Any]:
    decision = dict(getattr(owner, "_last_title_extraction_debug", {}) or {})
    if decision and not _title_decision_matches_url(decision, url):
        return {}
    return decision


def build_board_post_memo(reg_date_val: str, author: Optional[str], department: Optional[str]) -> str:
    """
    PHP homepage.htm 메모(작성일·글쓴이)와 맞춘 자동 메모 문자열.
    - 작성자·부서가 둘 다 있고 서로 다르면 글쓴이/부서를 각각 한 줄씩.
    - 그 외에는 작성자 우선, 없으면 부서명만 글쓴이 줄에 표시.
    """
    date_s = (reg_date_val or "").strip() or "-"
    a = (author or "").strip()
    d = (department or "").strip()
    lines = [f"작성일: {date_s}"]
    if a and d and a != d:
        lines.append(f"글쓴이: {a}")
        lines.append(f"부서: {d}")
    else:
        w = a or d or "-"
        lines.append(f"글쓴이: {w}")
    return "\n".join(lines)


def extract_board_content_updated_at(*, html: str = "", url: str = "") -> str:
    """Return only an explicitly labeled modified date; keep empty when absent."""
    if not html:
        return ""
    try:
        dates = extract_post_dates(html, post_url=url or "")
        modified_dt = dates.get("modified") if isinstance(dates, dict) else None
        if modified_dt:
            return modified_dt.strftime("%Y-%m-%d %H:%M:%S")
    except Exception:
        return ""
    return ""


_BOARD_AUTHOR_LABEL_RE = re.compile(
    r"^(?:작성자|등록자|등록인|작성인|글쓴이|담당자|성명|"
    r"담당부서|주관부서|시행부서|작성부서|부서명|부서|담당과|담당팀|담당기관)$",
    re.IGNORECASE,
)
_BOARD_AUTHOR_INLINE_RE = re.compile(
    r"(작성자|등록자|등록인|작성인|글쓴이|담당자|성명|"
    r"담당부서|주관부서|시행부서|작성부서|부서명|부서|담당과|담당팀|담당기관)"
    r"\s*[:：]\s*([가-힣A-Za-z0-9·ㆍ&()_\- *]{1,40})"
)
_BOARD_DEPT_LABEL_TOKENS = ("부서", "담당부서", "주관부서", "시행부서", "작성부서", "담당과", "담당팀", "담당기관")


def _extract_health_seoulmc_date_writer(soup: Any, url: str = "") -> Dict[str, str]:
    if soup is None:
        return {}
    try:
        parsed = urlparse(str(url or ""))
        host = (parsed.netloc or "").lower()
        path = (parsed.path or "").lower()
        qs = {str(k or "").lower(): v for k, v in parse_qs(parsed.query or "").items()}
    except Exception:
        return {}
    if host != "health.seoulmc.or.kr":
        return {}
    if not re.search(r"/healthseoul/[a-z0-9_]*view\.do$", path):
        return {}
    if "boardpid" not in qs:
        return {}
    try:
        node = (
            soup.select_one(".viewWrap .boardView > .endLine .date-writer")
            or soup.select_one(".boardView > .endLine .date-writer")
        )
    except Exception:
        node = None
    if node is None:
        return {}
    try:
        text = re.sub(r"\s+", " ", node.get_text(" ", strip=True) or "").strip()
    except Exception:
        text = ""
    if not text:
        return {}
    date_match = re.search(r"(\d{4})[-./](\d{1,2})[-./](\d{1,2})", text)
    if not date_match or "/" not in text:
        return {}
    date_text = f"{int(date_match.group(1)):04d}-{int(date_match.group(2)):02d}-{int(date_match.group(3)):02d}"
    author_text = text
    if "/" in author_text:
        author_text = author_text.split("/", 1)[0]
    if date_match:
        author_text = author_text.replace(date_match.group(0), "")
    author_text = re.sub(r"\s+", " ", author_text).strip(" /:-")
    return {
        "author": author_text,
        "department": author_text,
        "date": date_text,
        "raw": author_text,
    }


def _clean_board_author_candidate(value: Any) -> str:
    text = re.sub(r"\s+", " ", str(value or "")).strip(" \t\r\n:-：|/")
    if not text:
        return ""
    text = re.split(r"\s*(?:작성일|등록일|게시일|수정일|조회수|조회|전화번호|첨부파일)\s*[:：]?", text, maxsplit=1)[0]
    text = re.sub(r"\s+", " ", text).strip(" \t\r\n:-：|/")
    if len(text) > 40:
        text = text[:40].strip()
    return text if is_valid_content_author_value(text) else ""


def _extract_board_author_info_near_reg_date(soup: Any, html: str = "", url: str = "") -> Dict[str, Any]:
    if soup is None:
        if not html or not BeautifulSoup:
            return {}
        try:
            soup = BeautifulSoup(html, "html.parser")
        except Exception:
            return {}
    out: Dict[str, Any] = {}

    health_info = _extract_health_seoulmc_date_writer(soup, url=url)
    health_author = _clean_board_author_candidate(health_info.get("author"))
    if health_author:
        out.setdefault("author", health_author)
        out.setdefault("author_raw", health_author)
        out.setdefault("author_kind", "org")
        out.setdefault("department", health_author)
        out.setdefault("department_raw", health_author)

    def _apply(label: str, value: Any) -> None:
        val = _clean_board_author_candidate(value)
        if not val:
            return
        label_s = re.sub(r"\s+", "", str(label or ""))
        if any(tok in label_s for tok in _BOARD_DEPT_LABEL_TOKENS):
            out.setdefault("department", val)
            out.setdefault("department_raw", val)
        else:
            out.setdefault("author", val)
            out.setdefault("author_raw", val)
            out.setdefault("author_kind", "person")

    try:
        for tr in soup.find_all("tr", limit=80):
            cells = tr.find_all(["th", "td"], recursive=False)
            if len(cells) < 2:
                continue
            for idx in range(0, len(cells) - 1):
                label_norm = re.sub(r"\s+", "", cells[idx].get_text(" ", strip=True))
                if _BOARD_AUTHOR_LABEL_RE.match(label_norm):
                    _apply(label_norm, cells[idx + 1].get_text(" ", strip=True))
    except Exception:
        pass

    try:
        for dt in soup.find_all("dt", limit=80):
            label_norm = re.sub(r"\s+", "", dt.get_text(" ", strip=True))
            if not _BOARD_AUTHOR_LABEL_RE.match(label_norm):
                continue
            dd = dt.find_next_sibling("dd")
            if dd is not None:
                _apply(label_norm, dd.get_text(" ", strip=True))
    except Exception:
        pass

    if not (out.get("author") or out.get("department")):
        try:
            for node in soup.select(".view_info, .viewInfo, .board_view_info, .bbs_view_info, .post_info, .info, .boardInfo")[:20]:
                txt = node.get_text(" ", strip=True)
                for match in _BOARD_AUTHOR_INLINE_RE.finditer(txt):
                    _apply(match.group(1), match.group(2))
                    if out.get("author") or out.get("department"):
                        break
                if out.get("author") or out.get("department"):
                    break
        except Exception:
            pass

    if not (out.get("author") or out.get("department")):
        try:
            flat = soup.get_text(" ", strip=True)[:4000]
            for match in _BOARD_AUTHOR_INLINE_RE.finditer(flat):
                _apply(match.group(1), match.group(2))
                if out.get("author") or out.get("department"):
                    break
        except Exception:
            pass

    return out


_VIEW_COUNT_INLINE_RE = re.compile(r"(?<![0-9A-Za-z가-힣])(?:조회수|조회)\s*[:：]?\s*[0-9][0-9,]{0,10}")


def _strip_view_count_from_content(content: Any) -> str:
    text = str(content or "").replace("\x00", "").strip()
    if not text:
        return ""

    meta_tokens = ("작성일", "등록일", "수정일", "첨부파일", "파일", "내용", "작성자", "담당부서")
    cleaned_lines: List[str] = []
    for raw_line in text.splitlines():
        line = _VIEW_COUNT_INLINE_RE.sub(" ", raw_line)

        if "조회수" in line and len(line) <= 120:
            token_hits = sum(1 for token in meta_tokens if token in line)
            if token_hits >= 2:
                line = re.sub(r"(?<![0-9A-Za-z가-힣])조회수(?![0-9A-Za-z가-힣])", " ", line)

        line = re.sub(r"\s{2,}", " ", line).strip()
        if not line:
            continue
        if re.fullmatch(r"(?:조회수|조회)\s*[:：]?", line):
            continue
        cleaned_lines.append(line)

    return re.sub(r"\n{3,}", "\n\n", "\n".join(cleaned_lines)).strip()


def _strip_common_title_quality_prefix(value: str) -> str:
    text = re.sub(r"\s+", " ", str(value or "")).strip()
    if not text:
        return ""
    return re.sub(
        r"^\s*용어사전(?:\s*\([^)]*\))?\s*(?:[-:>|\uff5c]\s*)?",
        "",
        text,
        count=1,
        flags=re.IGNORECASE,
    ).strip()


def _looks_like_generic_dictionary_title(value: str) -> bool:
    text = re.sub(r"\s+", " ", str(value or "")).strip()
    if not text:
        return False
    compact = re.sub(r"[\s\-_:>|\uff5c()]+", "", text).lower()
    if compact in {"용어사전", "용어사전상세"}:
        return True
    if "용어사전" not in compact:
        return False
    return any(
        token in compact
        for token in (
            "한국저작권위원회",
            "저작권동향",
            "자료",
            "저작권기술용어",
            "영어불어",
        )
    )


def _is_weak_or_placeholder_title(value: str) -> bool:
    txt = str(value or "").strip()
    if not txt:
        return True
    if _looks_like_generic_dictionary_title(txt):
        return True
    if re.match(r"^https?://", txt, flags=re.IGNORECASE):
        return True
    compact_lower = re.sub(r"\s+", "", txt).lower()
    if compact_lower in {
        "내비게이션메뉴",
        "네비게이션메뉴",
        "navigationmenu",
        "navmenu",
    }:
        return True
    if compact_lower in {"파일", "첨부파일", "attachment", "attachments", "content", "contents"}:
        return True
    stripped_status = re.sub(
        r"^(?:(?:접수중|접수마감|접수예정|신청중|신청마감|모집중|모집마감|공고중|진행중|진행예정|상시)\s*(?:\([^)]*\))?\s*)+",
        "",
        txt,
    ).strip()
    stripped_status = re.sub(r"\s+\d{4}\.\d{1,2}\.\d{1,2}\.?\s*$", "", stripped_status).strip()
    if txt and not stripped_status:
        return True
    if txt == "제목 없음":
        return True
    low = txt.lower()
    if any(token in low for token in ("error", "err_", "에러", "오류", "error_title", "error_title_signature")):
        return True
    if txt.count(" < ") >= 1 or txt.count(" > ") >= 1:
        return True
    compact = txt.replace(" ", "")
    if compact.lower() in {
        "내비게이션메뉴",
        "네비게이션메뉴",
        "navigationmenu",
        "navmenu",
    }:
        return True
    if compact in {"공유하기", "담당자정보", "상세정보", "관련자료"}:
        return True
    if " " not in txt and re.fullmatch(r"[가-힣]{2,8}(시|군|구|청|구청|시청|군청|도청|교육청)", compact):
        return True
    return compact in {
        "교육·행사".replace(" ", ""),
        "교육행사",
        "민원안내",
        "공지사항",
        "시정소식",
        "카드뉴스",
        "프로모션별",
        "프로모션",
        "이벤트",
        "자료실",
        "갤러리",
    }


def _strip_leading_title_label(value: Any) -> str:
    txt = re.sub(r"\s+", " ", str(value or "")).strip()
    if not txt or txt == "제목 없음":
        return txt
    cleaned = re.sub(
        r"^\s*(?:제목|글제목|공고제목|채용제목|게시물명|게시글명|민원명|사무명)\s*[:：]?\s+(?=\S)",
        "",
        txt,
        count=1,
    ).strip()
    return cleaned or txt


