# 파일 직접 다운로드 URL 여부 (수집/추출 단계에서 차단용)
_FILE_DOWNLOAD_EXTENSIONS = (
    ".hwp", ".hwpx", ".pdf", ".zip", ".rar", ".7z", ".alz", ".egg",
    ".doc", ".docx", ".xls", ".xlsx", ".ppt", ".pptx",
    ".jpg", ".jpeg", ".png", ".gif", ".bmp", ".webp",
    ".mp3", ".mp4", ".avi", ".mov", ".wmv", ".txt", ".csv",
)
_FILE_DOWNLOAD_PATH_HINTS = ("filedown", "filedownload", "file_down", "fileDown", "download", "attachdown", "atchdown")


def _is_file_download_url(url: str) -> bool:
    """파일 직접 다운로드 URL이면 True. 수집/상세 처리 시 차단할 대상."""
    if not url or not isinstance(url, str):
        return False
    u = url.lower()
    if any(h in u for h in _FILE_DOWNLOAD_PATH_HINTS):
        return True
    path_part = urlparse(url).path or ""
    path_lower = path_part.lower()
    if any(path_lower.endswith(ext) or ext in path_lower for ext in _FILE_DOWNLOAD_EXTENSIONS):
        return True
    if any(ext in u for ext in _FILE_DOWNLOAD_EXTENSIONS):
        return True
    return False


# 비동기 백그라운드 메타 추출 유틸
async def _schedule_meta_extraction(job_id: str, db_name: str, html: str, url: str, selector_profile: Optional[dict] = None) -> None:
    """
    CPU/IO bound한 동기 메타 추출 함수를 쓰레드풀에서 실행하고,
    완료되면 SSE로 meta 이벤트를 발행한다.
    """
    return None


async def _disabled_schedule_meta_extraction_legacy(job_id: str, db_name: str, html: str, url: str, selector_profile: Optional[dict] = None) -> None:
    loop = asyncio.get_event_loop()
    try:
        # author extraction
        def _extract_author():
            try:
                return {}
            except Exception:
                return {}

        def _extract_contact():
            try:
                return {}
            except Exception:
                return {}

        author_info = await loop.run_in_executor(None, _extract_author)
        contact_info = await loop.run_in_executor(None, _extract_contact)

        payload = {
            "event": "meta_async",
            "job_id": job_id,
            "account_name": db_name,
            "author": author_info.get("author"),
            "department": author_info.get("department"),
            "author_kind": author_info.get("author_kind"),
            "author_raw": author_info.get("author_raw"),
            "department_raw": author_info.get("department_raw"),
            "contact_phone": contact_info.get("contact_phone"),
            "view_count": contact_info.get("view_count"),
            "timestamp": datetime.now().isoformat(),
            "source": "meta_async",
        }
        try:
            enqueue_sse_message(job_id, payload, db_name, "meta_async", priority=1)
        except Exception:
            # best-effort
            pass
    except Exception:
        return

# 네비게이션 또는 사이드바 앵커인지 판정하는 휴리스틱 (목록 vs 네비 구분)
def _is_nav_or_sidebar_anchor(a) -> bool:
    try:
        for parent in a.parents:
            name = (getattr(parent, "name", "") or "").lower()
            if name in _NAV_CONTAINER_TAGS:
                # 부모 태그가 nav/header/footer/aside인 경우 보통 네비게이션으로 간주
                # 단, 해당 부모가 실제로 게시글 목록 형태인지(다수의 <a> 포함, 상세페이지 패턴 존재)
                # 확인하여 목록일 경우 네비게이션 필터를 우회하도록 예외 처리.
                try:
                    links = parent.find_all("a", limit=50)
                    if links and len(links) >= 3:
                        # 링크 중 하나라도 상세페이지로 보이면 네비게이션이 아닐 가능성이 높음
                        for link in links:
                            try:
                                href = (link.get("href") or "").strip()
                                if href and is_detail_page_url(href):
                                    logger.debug("[NavHeuristic] parent looks like list container, allow anchors | parent=%s", getattr(parent, "attrs", {}))
                                    return False
                            except Exception:
                                continue
                except Exception:
                    pass
                return True
            try:
                pid = parent.get("id") or ""
            except Exception:
                pid = ""
            try:
                classes = parent.get("class") or []
            except Exception:
                classes = []
            if isinstance(classes, str):
                classes = [classes]
            for token in [pid, *classes]:
                if not token:
                    continue
                lt = str(token).lower()
                if any(h in lt for h in _NAV_CONTAINER_HINTS):
                    # 유사하게 토큰이 nav 힌트지만, 자식 링크를 검사해 목록 컨테이너면 네비 필터를 우회
                    try:
                        parent = getattr(a, "parent", None)
                        if parent:
                            # remove hard limit; check up to a reasonable cap for performance but prioritize detection
                            child_links = parent.find_all("a")
                            if child_links and len(child_links) >= 4:
                                # prefer scanning likely detail links first (heuristic: href patterns)
                                try:
                                    candidates = child_links[:200]  # cap to avoid pathological containers
                                except Exception:
                                    candidates = child_links
                                for child in candidates:
                                    href = (child.get("href") or "").strip()
                                    if href and is_detail_page_url(href):
                                        logger.debug("[NavHeuristic] class/id contains nav hint but parent has many detail links -> treat as content list")
                                        return False
                            # otherwise 네비게이션으로 판단
                    except Exception:
                        pass
                    return True
    except Exception:
        return False
    return False


def _extract_url_from_js_string(js_text: str, base: str) -> Optional[str]:
    """onclick/js 문자열에서 상세페이지로 변환 가능한 URL을 추출 시도 (모듈 레벨 헬퍼)"""
    try:
        if not js_text:
            return None
        s = str(js_text)
        # 1) 직접적인 상대/절대 링크 포함 패턴 (selectBbsNttView.do 등)
        m = re.search(r"(selectBbsNttView\\.do[^\\'\\\"\\)\\s>]*)", s, re.IGNORECASE)
        if m:
            return m.group(1)
        # 2) 쿼리 파라미터 형태의 nttNo/bbsNo 조합 추출하여 기본 뷰 URL 조합
        b = None
        n = None
        m1 = re.search(r"bbsNo\\s*[:=]\\s*['\\\"]?(\\d+)['\\\"]?", s, re.IGNORECASE)
        if m1:
            b = m1.group(1)
        m2 = re.search(r"nttNo\\s*[:=]\\s*['\\\"]?(\\d+)['\\\"]?", s, re.IGNORECASE)
        if m2:
            n = m2.group(1)
        # 다른 형태 (fn_egov, open 등)에서 숫자 추출
        if not b:
            m3 = re.search(r"bbsNo=(\\d+)", s, re.IGNORECASE)
            if m3:
                b = m3.group(1)
        if not n:
            m4 = re.search(r"nttNo=(\\d+)", s, re.IGNORECASE)
            if m4:
                n = m4.group(1)
        if b and n:
            return f"selectBbsNttView.do?bbsNo={b}&nttNo={n}"
        # 3) location.href = '...' 또는 open('...') 같은 문자열 내 URL 추출
        m5 = re.search(r"location\\.href\\s*=\\s*['\\\"]([^'\\\"]+)['\\\"]", s, re.IGNORECASE)
        if m5:
            return m5.group(1)
        m6 = re.search(r"open\\(\\s*['\\\"]([^'\\\"]+)['\\\"]", s, re.IGNORECASE)
        if m6:
            return m6.group(1)
    except Exception:
        return None
    return None


def _is_list_page_url(u: str) -> bool:
    if not u: return False
    lu = u.lower()

    # KISA 본인확인 지원포털: /bbs/{유형}/{글번호} 는 상세(cp만 있어도 목록으로 오판하지 않음)
    if is_identity_kisa_bbs_article_url(u):
        return False
    
    # ✅ [고양시청 전용 예외 보강]
    # 기능별 1줄 주석설명: 고양시청 도메인이면서 특정 상세페이지 패턴인 경우 리스트 판정에서 제외합니다.
    if "goyang.go.kr" in lu and "bd_selectbbsview.do" in lu:
        return False 

    # ✅ [춘천시청 및 공공기관 Clean URL 강화]
    # 기능별 1줄 주석설명: 춘천시청 등에서 확장자 없이 경로명(notice, legislative 등)만 있는 리스트 페이지를 판별합니다.
    if "chuncheon.go.kr" in lu:
        # 상세 경로·쿼리 식별자가 없을 때만 춘천형 clean URL 목록으로 간주
        if not any(k in lu for k in ["/detail/", "ctrtacctbookmngno="]) and not url_query_suggests_board_article_detail(
            u
        ):
            if any(k in lu for k in ["notice", "-info", "legislative", "contract", "daega"]):
                return True

    # 1. 한국형 게시판 특유의 목록 패턴 (brdList, postList, bbsList 등)
    # 기능별 1줄 주석설명: 정규식을 통해 접두어에 상관없이 'list.do' 등으로 끝나는 전형적인 목록 패턴을 감지합니다.
    if re.search(r'[a-z0-9]list\.(do|asp|jsp|php|html)', lu):
        return True
        
    # 2. 경로(Path) 분석
    try:
        path = (urlparse(u).path or "").strip().lower().rstrip("/")
        # 기능별 1줄 주석설명: 파일 경로 내에 list 확장자가 명시된 경우를 체크합니다.
        if any(p in path for p in ["list.do", "list.asp", "list.jsp"]):
            return True
        
        # 2-1. 경로 마지막 세그먼트가 'list'인 경우
        # 기능별 1줄 주석설명: 노원 수락휴 사례처럼 경로의 끝이 /list로 끝나는 리스트 전용 경로를 감지합니다.
        if path.endswith("/list") or path.split("/")[-1] == "list":
            return True

        # 3. [강화] 경로 키워드 직접 검사
        # 기능별 1줄 주석설명: 경로상에 게시판을 의미하는 키워드가 있고 상세 페이지 힌트가 없다면 리스트로 의심합니다.
        if any(x in path for x in ["/board/", "/notice/", "/bbs/"]) and "detail" not in path:
            # 상세 글·항목 식별 쿼리(알려진 키 또는 목록용이 아닌 숫자 키)가 없으면 목록으로 간주
            if not url_query_suggests_board_article_detail(u):
                return True

        # 4. [보너스] 파라미터에 list가 명시된 경우 (강력한 방어 로직)
        # 기능별 1줄 주석설명: URL 쿼리 파라미터에 mode=list와 같이 목록 상태임이 명시된 경우를 수집합니다.
        query = urlparse(u).query.lower()
        if "mode=list" in query or "task=list" in query:
            return True

    except Exception:
        pass

    return False


def _derive_list_url_from_detail_url(u: str) -> str:
    """Best-effort list URL for common Korean board detail URLs."""
    if not u:
        return ""
    try:
        parsed = urlparse(u)
        pairs = parse_qsl(parsed.query, keep_blank_values=True)
        if not pairs:
            return ""
        detail_keys = {
            "q_bbscttsn",
            "bbscttsn",
            "nttid",
            "ntt_id",
            "articleid",
            "articleseq",
            "q_nftcbbsmgtno",
            "nftcbbsmgtno",
            "seq",
            "no",
        }
        has_detail_key = any(str(k or "").lower() in detail_keys for k, _v in pairs)
        if not has_detail_key:
            return ""
        kept = [(k, v) for k, v in pairs if str(k or "").lower() not in detail_keys]
        kept_keys = {str(k or "").lower() for k, _v in kept}
        path_l = (parsed.path or "").lower()
        if "bd_selectbbs.do" in path_l and "q_bbscode" not in kept_keys:
            return ""
        if not kept:
            return ""
        candidate = urlunparse(
            (
                parsed.scheme,
                parsed.netloc,
                parsed.path,
                parsed.params,
                urlencode(kept, doseq=True),
                "",
            )
        )
        return candidate if candidate and candidate != u else ""
    except Exception:
        return ""


def _clean_common_list_page_title(text: Any) -> str:
    value = re.sub(r"\s+", " ", str(text or "")).strip()
    if not value:
        return ""
    parts = [p.strip() for p in re.split(r"\s*(?:>|›|»|/|\|)\s*", value) if p and p.strip()]
    if parts:
        value = parts[-1]
    compact = re.sub(r"\s+", "", value).strip().lower()
    if compact in {"", "home", "homepage", "main", "홈", "대표홈", "목록", "상세", "상세보기"}:
        return ""
    return value


