def _is_detail_view_url(u: str) -> bool:
    """
    상세(뷰) 페이지 URL인지 판별합니다.
    기존 로직을 유지하면서, 상세페이지가 아닌 것들을 걸러내는 제외 로직을 추가했습니다.
    """
    if not u:
        return False
        
    lu = u.lower()
    path = ""
    query = ""
    
    try:
        parsed = urlparse(u)
        path = (parsed.path or "").lower()
        query = (parsed.query or "").lower()
    except Exception:
        pass

    # 🛑 [추가] 상세페이지가 아닌 것이 확실한 '부정 패턴' 먼저 체크
    # 1. 문서/압축/이미지 파일 링크는 상세페이지가 아님
    if any(path.endswith(ext) for ext in ['.pdf', '.zip', '.hwp', '.docx', '.jpg', '.png', '.gif']):
        return False
        
    # 2. 페이징, 검색, 로그인, 가입 관련 키워드 제외
    exclude_keywords = ['login', 'join', 'search', 'index.do', 'index.jsp', 'index.asp']
    if any(k in path or k in query for k in exclude_keywords):
        return False
        
    # 3. 페이징 파라미터만 있고 글 식별 신호가 없으면 상세 아님
    try:
        qkeys = {k.lower() for k, _ in parse_qsl(urlparse(u).query or "")}
    except Exception:
        qkeys = set()
    if qkeys & BOARD_PAGINATION_QUERY_KEYS and not url_query_suggests_board_article_detail(u):
        return False

    # ✅ [기존 유지] 상세페이지 긍정 패턴 확인
    # selectBbsNttView.do, brdDetail.do, view.do, *View.do 등
    detail_path_keywords = ["view.do", "detail.do", "brddetail", "selectbbsnttview", "selectbbsview"]
    if any(keyword in path for keyword in detail_path_keywords):
        return True

    # 수락휴 등 경로 기반 상세: /bbs/notice/30, /bbs/notice/2 (마지막 세그먼트가 숫자)
    if "/bbs/" in path:
        segments = [s for s in path.rstrip("/").split("/") if s]
        if segments and re.match(r"^\d+$", segments[-1]):
            return True

    if url_query_suggests_board_article_detail(u):
        return True

    return False

def _normalize_host(host: str) -> str:
    # 호스트 정규화 (www. 접두사 제거)
    host = (host or "").lower()
    if host.startswith("www."):
        host = host[4:]
    return host


def _is_songpalearn_url(u: str) -> bool:
    """송파런(songpa.go.kr /learn 또는 learn.* 호스트) 구간 URL."""
    if not u:
        return False
    lu = (u or "").lower()
    if "songpa.go.kr" not in lu:
        return False
    return "/learn" in lu or lu.split("//", 1)[-1].lstrip("/").startswith("learn.")


def _is_songpakids_url(u: str) -> bool:
    """송파어린이문화회관(songpakids.com) URL 여부."""
    return bool(u and "songpakids.com" in (u or "").lower())


def _is_umppa_seoul_url(u: str) -> bool:
    """탄생육아 몽땅정보통(umppa.seoul.go.kr) — 서울시 임신·출산·육아 포털."""
    return bool(u and "umppa.seoul.go.kr" in (u or "").lower())


def _gwangjin_discover_path_allowed(path_lower: str) -> bool:
    """
    gwangjin.go.kr 탐색(discover)에서 목록·상세 확장 허용 경로.
    - /portal/bbs/* : 구청 통합게시판
    - …/bbs/*       : 보건(/health/bbs/) 등 서브사이트 게시판 — B0000003 등 동일 코드가 포털·보건에 공존
    - /edu/pgm/*    : 교육포털 프로그램
    """
    if not path_lower:
        return False
    if "/edu/pgm/" in path_lower:
        return True
    if "/portal/bbs/" in path_lower or path_lower.rstrip("/").endswith("/portal/bbs"):
        return True
    if "/bbs/" in path_lower:
        return True
    return False


def _is_gwangjin_contract_info_detail_url(url: str) -> bool:
    try:
        parsed = urlparse(url or "")
        host = (parsed.netloc or "").lower()
        path = (parsed.path or "").lower()
    except Exception:
        return False
    return (
        host.endswith("gwangjin.go.kr")
        and "/portal/singl/contractinfo/" in path
        and path.endswith("view.do")
    )


def _is_gwangjin_bbs_detail_url(url: str) -> bool:
    try:
        parsed = urlparse(url or "")
        host = (parsed.netloc or "").lower()
        path = (parsed.path or "").lower()
    except Exception:
        return False
    return (
        host.endswith("gwangjin.go.kr")
        and "/bbs/" in path
        and path.endswith("/view.do")
    )


def _extract_board_id(path: str) -> Optional[str]:
    # path에서 '/bbs/{board_id}/' 형태로 보드 아이디를 추출
    try:
        m = re.search(r"/bbs/([^/]+)/", path or "", re.IGNORECASE)
    except Exception:
        m = None
    if not m:
        return None
    return m.group(1)


def _extract_menu_no(url: str) -> Optional[str]:
    # URL 쿼리에서 menu 번호를 안전하게 추출 (menu_cd 추가)
    try:
        if not url: return None
        parsed = urlparse(url)
    except Exception:
        return None
    
    qs = parse_qs(parsed.query or "")
    # oka.go.kr은 주로 menu_cd를 사용하므로 목록에 추가
    for key in (
        "menu_cd",
        "menuNo",
        "mid",
        "menuno",
        "menu_no",
        "menu",
        "ctgryCd",
        "ctgry_cd",
        "ctgrycd",
        "categoryCd",
        "category_cd",
    ):
        if key in qs and qs[key]:
            return str(qs[key][0])
        # 대소문자 구분 없이 한 번 더 확인
        for k, v in qs.items():
            if k.lower() == key.lower() and v:
                return str(v[0])
    return None


def _extract_board_param(url: str) -> Optional[str]:
    # URL 쿼리에서 보드 식별 파라미터(bbsId/bbs_id/boardId 등)를 추출
    try:
        parsed = urlparse(url)
    except Exception:
        return None
    qs = parse_qs(parsed.query or "")
    for key in ("bbsId", "bbs_id", "bbsCd", "bbs_cd", "boardId", "board_id"):
        if key in qs and qs[key]:
            return str(qs[key][0])
        for k, v in qs.items():
            if k.lower() == key.lower() and v:
                return str(v[0])
    return None


def _is_same_board_scope(base_url: str, candidate_url: str) -> bool:
    # 두 URL이 같은 게시판(스코프)에 속하는지 판정 (호스트/board id/menu 비교)
    try:
        base = urlparse(base_url)
        cand = urlparse(candidate_url)
    except Exception:
        return False
    if _normalize_host(base.netloc) != _normalize_host(cand.netloc):
        return False
    # 최상위 도메인에서 시작한 경우는 제한하지 않음
    try:
        if (base.path or "").strip() in ("", "/") and not base.query and not base.fragment:
            return True
    except Exception:
        pass
    # 추출 값들 명시적으로 계산하여 디버그 로그 출력
    base_board = _extract_board_id(base.path or "") or None
    base_menu = _extract_menu_no(base_url) or None
    cand_board_param = _extract_board_param(candidate_url) or None
    cand_board = _extract_board_id(cand.path or "") or None
    cand_menu = _extract_menu_no(candidate_url) or None

    logger.debug(
        "[BoardScope][check] base_url=%s base_board=%s base_menu=%s candidate_url=%s cand_board_param=%s cand_board=%s cand_menu=%s",
        base_url,
        base_board,
        base_menu,
        candidate_url,
        cand_board_param,
        cand_board,
        cand_menu,
    )

    if not base_board:
        logger.debug("[BoardScope][check] base_board missing -> allow")
        return True
    if cand_board_param:
        res = cand_board_param.lower() == base_board.lower()
        logger.debug("[BoardScope][check] compare cand_board_param %s == %s -> %s", cand_board_param, base_board, res)
        return res
    if cand_board:
        res = cand_board.lower() == base_board.lower()
        logger.debug("[BoardScope][check] compare cand_board %s == %s -> %s", cand_board, base_board, res)
        return res
    if base_menu and cand_menu:
        res = base_menu == cand_menu
        logger.debug("[BoardScope][check] compare menu %s == %s -> %s", base_menu, cand_menu, res)
        return res
    logger.debug("[BoardScope][check] no matching board/menu -> deny")
    return False


def _candidate_matches_board_strict(candidate_url: str, base_board: Optional[str], base_menu: Optional[str]) -> bool:
    """
    더 엄격한 판정: base_board가 주어지면 candidate는 반드시
      - path에 '/bbs/{base_board}/' 포함 또는
      - 쿼리 파라미터(bbsId, bbs_id, bbsCd, boardId 등)에 base_board가 포함 또는
      - base_menu와 동일한 menuNo 파라미터를 가질 것
    """
    # 엄격 모드: candidate URL이 주어진 base_board/base_menu와 정확히 일치하는지 확인
    if not base_board:
        return True
    try:
        parsed = urlparse(candidate_url)
    except Exception:
        return False
    # 1) path 기반
    try:
        cand_board = _extract_board_id(parsed.path or "") or ""
        if cand_board and cand_board.lower() == base_board.lower():
            return True
    except Exception:
        pass
    # 2) 쿼리 파라미터 기반
    try:
        cand_board_param = _extract_board_param(candidate_url)
        if cand_board_param and cand_board_param.lower() == base_board.lower():
            return True
    except Exception:
        pass
    # 3) menuNo 비교 보완
    try:
        if base_menu:
            cand_menu = _extract_menu_no(candidate_url)
            if cand_menu and cand_menu == base_menu:
                return True
    except Exception:
        pass
    # 디버그: 불일치 시 로그 기록
    logger.debug(
        "[BoardScope][strict] candidate=%s base_board=%s base_menu=%s -> result=%s",
        candidate_url,
        base_board,
        base_menu,
        False,
    )
    return False


