def _extract_web_title_from_html(html: str, url: str = "") -> str:
    """
    <title> 또는 og:title 기반의 '웹(탭) 타이틀'을 best-effort로 추출한다.
    - downloads JSON에서 LLM 후처리용 fallback 메타로만 사용한다.
    """
    # HTML에서 og:title/meta title 혹은 <title> 태그로부터 웹 타이틀을 추출 (fallback 용도)
    if not html:
        return ""
    try:
        def _clean_title(v: str) -> str:
            return re.sub(r"\s+", " ", str(v or "")).strip()

        def _split_site_suffix(v: str) -> str:
            txt = _clean_title(v)
            if not txt:
                return ""
            for sep in (" | ", " ｜ ", " - ", " – ", " — ", " :: ", " · "):
                if sep in txt:
                    parts = [p.strip() for p in txt.split(sep) if p and p.strip()]
                    if parts:
                        return parts[0]
            return txt

        def _is_noise_web_title(v: str) -> bool:
            txt = _clean_title(v)
            if not txt:
                return True
            if txt in {"교육·행사", "교육행사", "새소식", "공지사항", "시정소식"}:
                return True
            if txt in {"동작구", "동작예약", "상세보기", "목록", "포털사이트"}:
                return True
            if txt in {
                "시설(상세)",
                "교육/강좌(상세)",
                "자치회관(상세)",
                "문화/행사(상세)",
                "생활서비스(상세)",
            }:
                return True
            if "포털사이트" in txt:
                return True
            return False

        # 우선 og:title (없으면 <title>)
        if BeautifulSoup:
            try:
                soup = BeautifulSoup(html, "html.parser")  # type: ignore[operator]
                try:
                    if url and "k-cohesion.go.kr" in (url or "").lower() and "/pcnc/contents/" in (url or "").lower():
                        detail_title = soup.select_one(".board_detail_wrap .detail_tit")
                        if detail_title:
                            detail_title = copy.copy(detail_title)
                            for category in detail_title.select(".category"):
                                category.decompose()
                            kcohesion_title = _clean_title(detail_title.get_text(" ", strip=True))
                            if kcohesion_title and not _is_noise_web_title(kcohesion_title):
                                return kcohesion_title
                except Exception:
                    pass
                try:
                    scored_title = extract_title_with_scores(soup, url=url or "")
                    parser_title = _clean_title(scored_title.get("title") or "")
                    if (
                        parser_title
                        and int(scored_title.get("title_score") or 0) >= 60
                        and not _is_noise_web_title(parser_title)
                    ):
                        return parser_title
                except Exception:
                    pass
                try:
                    if url and is_anseong_url(url):
                        anseong_title = _clean_title(extract_anseong_title(soup, url=url) or "")
                        if anseong_title and not _is_noise_web_title(anseong_title):
                            return anseong_title
                except Exception:
                    pass
                try:
                    if url and is_gm_static_info_url(url):
                        gm_static_title = _clean_title(extract_gm_static_info_title(soup, url=url) or "")
                        if gm_static_title and not _is_noise_web_title(gm_static_title):
                            return gm_static_title
                except Exception:
                    pass
                try:
                    if url and is_songpa_main_office_url(url):
                        songpa_title = _clean_title(extract_songpa_title(soup, url=url) or "")
                        _songpa_title_trace(
                            "web_title_songpa_title_candidate",
                            url=url,
                            songpa_title=songpa_title,
                            is_noise=_is_noise_web_title(songpa_title),
                        )
                        if songpa_title and not _is_noise_web_title(songpa_title) and songpa_title != "제목 없음":
                            _songpa_title_trace("web_title_return_songpa_title", url=url, selected=songpa_title)
                            return songpa_title
                        songpa_web_title = _clean_title(extract_songpa_web_title(soup, url=url) or "")
                        _songpa_title_trace(
                            "web_title_songpa_web_title_candidate",
                            url=url,
                            songpa_web_title=songpa_web_title,
                            is_noise=_is_noise_web_title(songpa_web_title),
                        )
                        if songpa_web_title and not _is_noise_web_title(songpa_web_title):
                            _songpa_title_trace("web_title_return_songpa_web_title", url=url, selected=songpa_web_title)
                            return songpa_web_title
                except Exception:
                    pass
                try:
                    if url and is_sungdong_contract_detail_url(url):
                        sungdong_contract_title = _clean_title(extract_sungdong_contract_title(soup, url=url) or "")
                        if sungdong_contract_title and not _is_noise_web_title(sungdong_contract_title):
                            return sungdong_contract_title
                except Exception:
                    pass
                try:
                    common_list_title = _clean_title(_extract_common_list_page_title(soup, url=url) or "")
                    _songpa_title_trace(
                        "web_title_common_list_candidate",
                        url=url,
                        common_list_title=common_list_title,
                    )
                    if common_list_title:
                        _songpa_title_trace("web_title_return_common_list", url=url, selected=common_list_title)
                        return common_list_title
                except Exception:
                    pass
                try:
                    if url and is_youthcenter_bbs_view_url(url):
                        v = _clean_title(extract_youthcenter_board_title(soup, url=url, html=html) or "")
                        if v and not _is_noise_web_title(v):
                            return v
                    if url and is_youthcenter_policy_detail_url(url):
                        v = _clean_title(extract_youthcenter_policy_title(soup, url=url, html=html) or "")
                        if v and not _is_noise_web_title(v):
                            return v
                    if url and is_youthcenter_openapi_doc_url(url):
                        v = _clean_title(extract_youthcenter_openapi_title(soup) or "")
                        if v and not _is_noise_web_title(v):
                            return v
                except Exception:
                    pass
                try:
                    if url and "miryang.go.kr" in (url or "").lower():
                        for sel in (
                            "#contents .cont-top h2.tit",
                            "#contents .cont-top .tit",
                            ".board-view-title h3",
                            "table.board_view_table th[colspan] > b",
                            "table.board_view_table tr:first-child th > b",
                            "table.board_view_table th > b",
                            ".inboxRead .headinfo > h3.BoR-h2",
                            ".inboxRead .headinfo > h2.BoR-h2",
                            "h3.BoR-h2",
                            "h2.BoR-h2",
                            "h3.tit",
                            ".view_tit",
                        ):
                            el = soup.select_one(sel)
                            if not el:
                                continue
                            v = _clean_title(el.get_text(" ", strip=True) or "")
                            if v and not _is_noise_web_title(v):
                                return v
                except Exception:
                    pass
                try:
                    from backend.board.yongin_board import extract_yongin_general_title

                    yongin_title = _clean_title(extract_yongin_general_title(soup) or "")
                    if yongin_title and not _is_noise_web_title(yongin_title):
                        return yongin_title
                except Exception:
                    pass
                try:
                    from backend.board.asimc_board import extract_asimc_title, is_asimc_url

                    if url and is_asimc_url(url):
                        asimc_title = _clean_title(extract_asimc_title(soup, url=url) or "")
                        if asimc_title and not _is_noise_web_title(asimc_title):
                            return asimc_title
                except Exception:
                    pass
                try:
                    for sel in (
                        ".teacher_cnt strong.area_title",
                        ".teacher_cnt .area_title",
                        "strong.area_title",
                        ".area_title",
                        "form.form-inline .program-reserv-wrap .subject h4",
                        ".program-reserv-wrap .subject h4",
                        "h3.h0.title",
                        ".h0.title",
                        ".poll_view > h4",
                        ".article-header h1.article-subject",
                        ".article-header h1.article_subject",
                        ".article-header h4.article-subject",
                        ".article-header h4.article_subject",
                        "h1.article-subject",
                        "h1.article_subject",
                        "h4.article-subject",
                        "h4.article_subject",
                        ".subject h4",
                        "h4.subject",
                        "#go_content .subject",
                        "#contentDiv .subject",
                        ".subject",
                        "h1.article-subject",
                        "h1.article_subject",
                        ".article-header .main-title",
                        ".main-title",
                    ):
                        el = soup.select_one(sel)
                        if el is None:
                            continue
                        v = _clean_title(el.get_text(" ", strip=True))
                        if v and not _is_noise_web_title(v):
                            return v
                except Exception:
                    pass
                try:
                    og = soup.select_one("meta[property='og:title']")
                    if og is not None:
                        v = _split_site_suffix(og.get("content") or "")
                        if v and not _is_noise_web_title(v):
                            return v
                except Exception:
                    pass
                try:
                    for meta_name in ("title", "subject", "dc.title"):
                        tag = soup.select_one(f"meta[name='{meta_name}']")
                        if tag is not None:
                            v = _split_site_suffix(tag.get("content") or "")
                            if v and not _is_noise_web_title(v):
                                return v
                except Exception:
                    pass
                try:
                    tag = soup.select_one("meta[property='og:site_name']")
                    if tag is not None:
                        v = _split_site_suffix(tag.get("content") or "")
                        if v and not _is_noise_web_title(v):
                            return v
                except Exception:
                    pass
                try:
                    if soup.title and soup.title.string:
                        v = _split_site_suffix(soup.title.string)
                        if v and not _is_noise_web_title(v):
                            return v
                except Exception:
                    pass
                try:
                    h1 = soup.find("h1")
                    if h1:
                        v = _clean_title(h1.get_text(" ", strip=True))
                        if v and not _is_noise_web_title(v):
                            return v
                except Exception:
                    pass
            except Exception:
                pass
        # BeautifulSoup이 없거나 실패하면 정규식 fallback
        import re as _re
        m = _re.search(r"<title[^>]*>(.*?)</title>", html, flags=_re.IGNORECASE | _re.DOTALL)
        if not m:
            return ""
        v = _split_site_suffix(m.group(1) or "")
        return v
    except Exception:
        return ""


# HTML/text에서 '페이지 없음' 또는 오류 페이지 여부를 판별하여 스킵 사유 문자열 반환
from typing import Optional

def _normalize_page_signal_text(value: str) -> str:
    return re.sub(r"\s+", "", str(value or "")).lower()

def _looks_like_invalid_page(*, html: str, text: str, url: str = "") -> Optional[str]:
    try:
        h_low = (html or "").lower()
        t_low = (text or "").lower()
        h_norm = _normalize_page_signal_text(html)
        t_norm = _normalize_page_signal_text(text)

        config = PAGE_VALIDATION_CONFIG

        # 1. HTTP 표준 에러
        if "404 not found" in h_low or "page not found" in h_low:
            return "http_404_or_not_found"

        # 2. 한국형 404
        if "요청하신 페이지" in (html or "") and "찾을 수 없" in (html or ""):
            return "page_not_found_kr"

        # 3. 로그인 구조 (password input)
        has_password_input = (
            'type="password"' in h_low or
            "type='password'" in h_low
        )

        # 4. 로그인 키워드
        login_indicators = [
            "로그인이 필요합니다",
            "아이디를 입력하세요",
            "비밀번호를 입력하세요",
            "member/login",
            "login_form"
        ]

        login_hit = any(indicator in t_low or indicator in h_low for indicator in login_indicators)

        # ⭐ login keyword + password input 둘 다 있을 때만 로그인 페이지
        if login_hit and has_password_input:
            return "login_page_keyword"

        # ⭐ 본문 존재 여부 확인
        from bs4 import BeautifulSoup
        soup = BeautifulSoup(html, "lxml")
        try:
            title_text = soup.title.get_text(" ", strip=True) if soup.title else ""
        except Exception:
            title_text = ""
        title_norm = _normalize_page_signal_text(title_text)
        if title_norm in {"error", "err", "404", "403", "500", "502", "503", "badrequest", "notfound"}:
            return "error_page_title_exact"
        if any(sig in title_norm for sig in ("servererror", "runtimeerror", "error_title", "error_title_signature")):
            return "error_page_title_signature"

        if url and is_gangnam_family_url(url) and is_gangnam_error_page(soup):
            return "gangnam_error_page"

        if (
            url
            and "songpa.go.kr" in (url or "").lower()
            and "selectbbsnttview.do" in (url or "").lower()
            and "decodeuricomponent" in h_low
            and ("history.back" in h_low or "window.history.back" in h_low)
        ):
            return "songpa_expired_or_deleted_notice"

        sungdong_notice_reason = sungdong_cffdn_invalid_notice_reason(html=html, url=url)
        if sungdong_notice_reason:
            return sungdong_notice_reason

        access_denied_signals = (
            "권한이없습니다",
            "접근이제한",
            "접근제한",
            "접근권한없음",
            "접근거부",
            "permissiondenied",
            "accessdenied",
            "forbidden",
        )
        restricted_notice_title_signals = (
            "안내메시지",
            "안내message",
            "alertmessage",
        )
        if any(sig in title_norm for sig in restricted_notice_title_signals):
            if any(sig in t_norm or sig in h_norm for sig in access_denied_signals):
                return "access_restricted_notice_page"
        if any(sig in t_norm for sig in access_denied_signals):
            if "내용:" in (text or "") or "sd.go.kr" in h_low or "sd.go.kr" in t_low:
                return "access_restricted_notice_page"

        has_content = any(
            soup.select_one(sel) for sel in config["content_selectors"]
        )

        if (
            url
            and is_gangnam_main_board_view_url(url)
            and soup.select_one(".bbs-view .post-content")
        ):
            return None

        if (
            url
            and "gm.go.kr" in (url or "").lower()
            and "history.back" in h_low
            and "alert(" in h_low
            and not has_content
        ):
            return "gm_invalid_request_notice_page"

        generic_error_signals = (
            "페이지오류",
            "에러페이지",
            "요청하신페이지를찾을수없습니다",
            "페이지를찾을수없습니다",
            "존재하지않습니다",
            "삭제되었거나존재하지않습니다",
            "불편을드려죄송합니다",
            "서비스이용에불편을드려죄송합니다",
            "잠시후다시",
            "잘못된접근",
            "invalidrequest",
            "errorpage",
        )

        visible_error_hit = any(sig in title_norm or sig in t_norm for sig in generic_error_signals)
        html_error_hit = any(sig in h_norm for sig in generic_error_signals)

        if any(sig in title_norm for sig in generic_error_signals):
            return "error_title_signature"

        if (
            url
            and "edu.ingang.go.kr" in (url or "").lower()
            and any(part in (url or "") for part in ("/highView", "/middleView"))
            and (
                soup.select_one("#contents")
                or soup.select_one(".teacher_cnt")
                or soup.select_one(".teacher_cnt strong.area_title")
            )
        ):
            return None

        # 온통청년 상세는 초기 HTML의 스크립트 안에
        # "데이터가 존재하지 않습니다." 문구를 상시 포함한다.
        # 실제 본문은 AJAX로 채워지므로, 보이는 텍스트/타이틀에 오류 신호가 없으면
        # generic_error_page로 오탐하지 않도록 예외 처리한다.
        if (
            not has_content
            and html_error_hit
            and not visible_error_hit
            and url
            and is_youthcenter_bbs_view_url(url)
        ):
            return None

        if (
            url
            and _is_gwangjin_contract_info_detail_url(url)
            and soup.select_one("#content")
            and len((soup.select_one("#content").get_text(" ", strip=True) or "").strip()) >= 80
        ):
            return None

        if not has_content and (html_error_hit or visible_error_hit):
            return "generic_error_page"

        # 5. 오류 키워드 + 본문 없음
        if not has_content:
            if any(k in t_low for k in config["error_keywords"]):
                return "no_post_content_kr"

    except Exception:
        return None

    return None


def _looks_like_dongjak_test_program_page(*, url: str, title: str, text: str) -> bool:
    if not url:
        return False
    try:
        parsed = urlparse(url)
        host = (parsed.netloc or "").lower()
        path = (parsed.path or "").lower()
        if not host.endswith("dongjak.go.kr"):
            return False
        if "/yeyak/progrm/master/online/view.do" not in path:
            return False

        title_low = re.sub(r"\s+", " ", str(title or "")).strip().lower()
        text_low = re.sub(r"\s+", " ", str(text or "")).strip().lower()
        text_norm = _normalize_page_signal_text(text)

        matched_signals: List[str] = []
        if "결제시스템테스트중입니다" in text_norm:
            matched_signals.append("payment_test_notice")
        if "02-9999-9999" in text_low or "0299999999" in text_norm:
            matched_signals.append("placeholder_phone")
        if title_low == "test":
            matched_signals.append("title_test")
        if re.search(r"(모집명|교육장소)\s*test\b", text_low):
            matched_signals.append("field_test")

        # 실제 예약 상세와 경로는 같으므로, 테스트 문구/placeholder 신호가 2개 이상일 때만 차단한다.
        return len(matched_signals) >= 2 and any(
            signal in matched_signals for signal in ("payment_test_notice", "placeholder_phone")
        )
    except Exception:
        return False


def _runtime_result_invalid_drop_reason(
    *,
    title: Any = "",
    web_title: Any = "",
    content: Any = "",
    runtime_output: Optional[Dict[str, Any]] = None,
) -> str:
    """Detect parsed error pages that slipped past the cheap HTML invalid-page guard."""
    runtime_output = dict(runtime_output or {})
    candidates: List[str] = []
    for value in (title, web_title):
        text = str(value or "").strip()
        if text:
            candidates.append(text)
    try:
        for section_name in ("post_info", "learning_result", "display"):
            section = runtime_output.get(section_name)
            if isinstance(section, dict):
                for key in ("title", "subject", "web_title"):
                    text = str(section.get(key) or "").strip()
                    if text:
                        candidates.append(text)
    except Exception:
        pass

    for text in candidates:
        compact = _normalize_runtime_compare_text(text)
        low = text.lower().strip()
        if compact in {"error", "err", "404", "403", "500", "502", "503", "badrequest", "notfound"}:
            return "parsed_error_title_exact"
        if any(token in low for token in ("error_title", "error_title_signature", "server error", "runtime error")):
            return "parsed_error_title_signature"

    compact_content = _normalize_runtime_compare_text(str(content or "")[:2000])
    if len(compact_content) <= 80 and compact_content in {
        "error",
        "404",
        "500",
        "403",
        "notfound",
        "pageerror",
        "errorpage",
    }:
        return "parsed_error_content_only"
    return ""


@dataclass
class _DetailItem:
    url: str
    board_url: str = ""           
    type: str = "post"           
    cate_match: str = ""
    force_detail: bool = False
    force_relearn: bool = False
    disable_playwright: bool = False
    reg_date: Optional[datetime] = None
    reg_date_str: Optional[str] = None
    subject: Optional[str] = ""    
    title: Optional[str] = ""     
    direct_attachments: Optional[List[Dict[str, Any]]] = None
    author_info: Optional[Dict[str, Any]] = None
    cate1: str = ""
    cate2: str = ""
class BoardContentWorkflow:
    # router에서 주입/참조하는 필드들(인터페이스 호환)
    job_id: str = ""
    db_name: str = ""
    chat_bot_id: str = ""
    colle: str = "board"
    server_domain: Optional[str] = None
    craw_id: Optional[str] = None
    unique_id: Optional[str] = None
    cate1: Optional[str] = None
    cate2: Optional[str] = None
    memo: Optional[str] = None

    # 클래스 초기화: 상태, 통계, 내부 락 및 런타임 플래그 초기화
    def __init__(self) -> None:
        # integrated_workflow.WorkflowState 기준:
        # - INIT / RUNNING / STOPPING / COMPLETED / ERROR / CANCELLED
        # 일부 배포본에서 IDLE이 없어서 크래시가 발생할 수 있어 INIT로 시작한다.
        try:
            self.state: WorkflowState = getattr(WorkflowState, "INIT")  # type: ignore[assignment]
        except Exception:
            # 최후 fallback (상태 표시만 목적이므로 RUNNING으로라도 시작)
            self.state = WorkflowState.RUNNING
        self.final_status: str = "running"
        self.is_running: bool = False
        self.stop_event: asyncio.Event = asyncio.Event()
        self._stop_requested: bool = False
        self._stop_requested_at: Optional[float] = None
        self._hard_stop: bool = False
        self._hard_stop_reason: Optional[str] = None
        self._hard_stop_at: Optional[float] = None
        # 자동 중단(기간 초과) 시에도 "completed"로 마무리하기 위한 플래그
        self._auto_stop_as_completed: bool = False
        self._auto_stop_reason: Optional[str] = None
        # SFTP support removed: session key no longer used

        self.start_date: Optional[datetime] = None
        self.end_date: Optional[datetime] = None
        self.duplicate_repair_created_at_start: Optional[datetime] = None
        self.duplicate_repair_created_at_end: Optional[datetime] = None
        self.duplicate_title_dry_run: bool = False
        self._scope_identities: List[str] = []
        self._scope_path_prefix: str = ""
        self._scope_path_fallback_prefixes: List[str] = []
        self._scope_source_url: str = ""
        self.progress_callback = None
        # 탐색 중 reg_date가 관찰되었는지 플래그 (IntegratedWorkflow와 연동용)
        self._observed_reg_date: bool = False
        self.colle = "board"
        # 첨부 파일 파이프라인(FileDownloadWorkflow) 전용 플래그·훅(게시판 본문 크롤에서는 False/None)
        self.is_attachment_file_crawl_workflow: bool = False
        self._preexplored_start_urls_lock_scan_total: bool = True
        self._sync_scan_count_before_finalize_snapshot = None  # Optional[Callable[[], None]]
        # 외부 전송: False=내부 서버 전용(rsync/SFTP 스킵), True=다운로드 후 웹서버 동기화
        self.sync_after_download: bool = False

        # stats (router.run_workflow_task가 참고)
        self.stats: Dict[str, Any] = {
            "scan_count": 0,
            "collection_count": 0,
            # ✅ 사용자 정의 카운트 정책(요청사항):
            # - 저장(save_count): DB 저장이 "성공"한 건만 증가 (실패/스킵은 포함하지 않음)
            # - 학습(study_count): 임베딩 완료 + status 업데이트까지 "성공"한 건만 증가 (실패/스킵 포함하지 않음)
            #
            # NOTE: 워크플로우 종료/대기 판단을 위해 성공 카운트와 별도로 "done 카운트"를 유지한다.
            "save_count": 0,          # 성공만
            "save_done_count": 0,     # 성공/실패 포함(내부 완료 판단용)
            "save_success_count": 0,
            "save_failed_count": 0,
            "study_count": 0,         # 성공만
            "study_done_count": 0,    # 성공/실패/스킵 포함(내부 완료 판단용)
            "study_success_count": 0,
            "study_failed_count": 0,
            "study_skipped_count": 0,
            "stats_revision": 0,
        }
        self._stats_revision: int = 0

        # If True, lock scan_count to the pre-explored value (do not allow further updates)
        self._lock_scan_count_from_pre_explored: bool = False
        # If set, this holds the initial scan_count provided by pre_explored_url (int)
        from typing import Optional as _Optional_type
        self._pre_explored_scan_count: _Optional_type[int] = None

        self._seen_scan: Set[str] = set()
        self._seen_collection: Set[str] = set()
        self._seen_save: Set[str] = set()
        self._seen_study: Set[str] = set()
        self._job_result_records: Dict[str, Dict[str, Any]] = {}
        # 완료 카운트 중복 증가 방지(동시 detail 워커 대비)
        self._counted_collection_keys: Set[str] = set()
        self._counted_save_keys: Set[str] = set()
        self._counted_study_keys: Set[str] = set()
        self._stats_lock = asyncio.Lock()
        self._last_page_summary: Optional[Dict[str, Any]] = None
        try:
            self._empty_page_streak_limit = max(1, int(os.getenv("BOARD_CONTENT_EMPTY_PAGE_STREAK_THRESHOLD", "20") or "20"))
        except Exception:
            self._empty_page_streak_limit = 20
        self._empty_page_streak = 0
        try:
            self._no_new_page_streak_limit = max(
                1, int(os.getenv("BOARD_CONTENT_NO_NEW_PAGE_STREAK_THRESHOLD", "10") or "10")
            )
        except Exception:
            self._no_new_page_streak_limit = 10
        self._no_new_page_streak = 0
        # 날짜 범위 초과 페이지 연속 감지(완료 지연 방지)
        try:
            self._out_of_range_page_streak_limit = max(
                1, int(os.getenv("BOARD_CONTENT_OUT_OF_RANGE_PAGE_STREAK_THRESHOLD", "3") or "3")
            )
        except Exception:
            self._out_of_range_page_streak_limit = 3
        self._out_of_range_page_streak = 0
        # 기간 필터를 통과한 "상세(detail) URL" 집합
        # - 정책: collection_count는 "DB 중복이 아닌 것만" 증가해야 하므로,
        #   여기에는 반드시 canonical key(정규화 URL)만 넣는다.
        self._seen_filtered_detail: Set[str] = set()
        # ✅ DB 중복 체크 캐시(선별 단계):
        # - 같은 URL에 대해 중복 조회를 반복하지 않도록 한다.
        self._db_dup_checked: Set[str] = set()
        self._db_dup_urls: Set[str] = set()
        self._dup_cache_lookup_log_counter: int = 0
        self._db_dup_context_lock = asyncio.Lock()
        self._db_dup_context: Optional[Dict[str, Any]] = None
        self._html_fetch_cache: Dict[str, str] = {}
        self._static_fetch_outcomes: Dict[str, Dict[str, Any]] = {}
        self._static_prefetch_empty_counts: Dict[str, int] = {}
        self._static_prefetch_empty_block_until: Dict[str, float] = {}
        self._static_prefetch_last_prune_at: float = 0.0
        # dedupe seen state for scoring-based duplicate detection
        try:
            from utils.dedupe import make_seen_state

            self._dedupe_seen_state = make_seen_state()
        except Exception:
            self._dedupe_seen_state = {"raw_urls": set(), "by_id": {}, "by_canon": {}, "processed": []}

        # ✅ 안전 기본값: 파이프라인 모드 플래그는 start_workflow에서 바로 참조된다.
        # 일부 배포본에서 __init__ 내 설정 블록이 누락/변형되어도 AttributeError가 나지 않게,
        # 먼저 기본값을 선언해 둔다.
        self.pipeline_detail_during_discover: bool = True
        # 글로벌 워커풀 사용 여부 (파일 파이프라인 포함)
        self.use_global_pool: bool = False

        self._learn_runtime_lock = asyncio.Lock()
        self._learn_redis = None
        self._learn_job_manager = None
        self._learn_job_progress = None
        # ✅ 학습 로그(운영 증거) 출력 제어
        # - 너무 많은 URL에서 매번 print하면 로그가 폭주하므로 기본은 50개당 1개 + 실패/느림은 항상 출력
        try:
            self._learn_log_every: int = int(os.getenv("BOARD_LEARN_LOG_EVERY", "50") or "50")
        except Exception:
            self._learn_log_every = 50
        self._learn_log_every = max(1, min(self._learn_log_every, 10_000))
        self._learn_log_counter: int = 0
        # 느림 기준(ms) - 이 이상이면 항상 로그 출력
        try:
            self._learn_slow_ms: int = int(os.getenv("BOARD_LEARN_SLOW_MS", "3000") or "3000")
        except Exception:
            self._learn_slow_ms = 3000
        self._learn_slow_ms = max(200, min(self._learn_slow_ms, 120_000))
        try:
            self._learn_async: bool = str(os.getenv("BOARD_CONTENT_LEARN_ASYNC", "1")).strip().lower() in ("1", "true", "yes", "on")
        except Exception:
            self._learn_async = True
        try:
            default_learn_conc = int(getattr(settings, "BOARD_CONTENT_LEARN_CONCURRENCY", _board_default_learn_concurrency()) or 1)
            learn_conc = min(default_learn_conc, _board_followup_workers_per_job())
        except Exception:
            learn_conc = _board_default_learn_concurrency()
        learn_conc = max(1, min(learn_conc, 128))
        self._learn_sem = asyncio.Semaphore(learn_conc)
        # 상세: 정적 실패 시 Playwright 전역 폴백 동시성 (기본 4, 상한 6 — 대량 URL 시 브라우저 폭주 방지)
        _dpw = _board_playwright_pool_size()
        _dpw = max(1, min(_dpw, 6))
        self._detail_pw_fallback_sem: asyncio.Semaphore = asyncio.Semaphore(_dpw)
        self._learn_tasks: Set[asyncio.Task] = set()
        # 메타 추출(작성자 등) 백그라운드 태스크 → workflow_runner가 완료 전 대기
        self._meta_extraction_tasks: Set[asyncio.Task] = set()
        self._background_misc_tasks: Set[asyncio.Task] = set()
        self._background_misc_task_labels: Dict[asyncio.Task, str] = {}
        self._background_aiojobs_scheduler: Any = None
        self._background_aiojobs_jobs: Set[Any] = set()
        self._slow_detail_background_seen: Set[str] = set()
        _sbg = _board_detail_workers_per_job()
        self._slow_detail_background_sem: asyncio.Semaphore = asyncio.Semaphore(max(1, min(_sbg, 6)))
        self._slow_detail_retry_queue: Optional[asyncio.Queue] = None
        self._slow_detail_retry_worker_tasks: Set[asyncio.Task] = set()
        self._slow_detail_retry_active_jobs: int = 0
        self._static_detail_retry_later: List[Any] = []
        self._static_detail_retry_later_keys: Set[str] = set()
        self._static_detail_retry_later_lock: asyncio.Lock = asyncio.Lock()
        # Board DB writes are funneled through a bounded post-save queue so
        # detail workers do not all compete for insert/update connections.
        try:
            self._post_save_async = str(
                os.getenv("BOARD_LEARN_LIST_SAVE_ASYNC", "1")
            ).strip().lower() in ("1", "true", "yes", "on")
        except Exception:
            self._post_save_async = True
        try:
            default_save_workers = int(getattr(settings, "BOARD_LEARN_LIST_SAVE_WORKERS", _board_followup_workers_per_job()) or _board_followup_workers_per_job())
            _post_save_workers = min(default_save_workers, _board_followup_workers_per_job())
        except Exception:
            _post_save_workers = 6
        self._post_save_worker_count: int = max(1, min(_post_save_workers, 16))
        try:
            _post_save_qmax = int(os.getenv("BOARD_LEARN_LIST_SAVE_QUEUE_MAXSIZE", "1000") or "1000")
        except Exception:
            _post_save_qmax = 1000
        self._post_save_queue_maxsize: int = max(1, min(_post_save_qmax, 100000))
        self._post_save_queue: Optional[asyncio.Queue] = None
        self._post_save_worker_tasks: Set[asyncio.Task] = set()
        self._post_save_active_jobs: int = 0
        self._post_save_last_health_log_ts: float = 0.0
        try:
            self._post_save_wait_on_finalize: bool = str(
                os.getenv("BOARD_LEARN_LIST_SAVE_WAIT_ON_FINALIZE", "0")
            ).strip().lower() in ("1", "true", "yes", "on")
        except Exception:
            self._post_save_wait_on_finalize = False
        try:
            default_save_db_conc = int(getattr(settings, "BOARD_LEARN_LIST_SAVE_DB_CONCURRENCY", _board_followup_workers_per_job()) or _board_followup_workers_per_job())
            _post_save_db_conc = min(default_save_db_conc, _board_followup_workers_per_job())
        except Exception:
            _post_save_db_conc = 6
        self._post_save_db_sem: asyncio.Semaphore = asyncio.Semaphore(max(1, min(_post_save_db_conc, 6)))
        _post_save_job_conc = int(getattr(self, "_post_save_worker_count", 6) or 6)
        self._post_save_job_sem: asyncio.Semaphore = asyncio.Semaphore(max(1, min(_post_save_job_conc, 16)))
        self._shadow_summary_row_ids: Set[int] = set()
        self._duplicate_shadow_html_cache: Dict[str, Optional[str]] = {}
        self._duplicate_shadow_html_inflight: Dict[str, asyncio.Task] = {}
        self._duplicate_shadow_title_cache: Dict[str, str] = {}
        self._duplicate_shadow_title_inflight: Dict[str, asyncio.Task] = {}
        self._category_rule_resolve_cache: Dict[str, Optional[Tuple[str, str]]] = {}
        _dup_bg = _board_followup_workers_per_job()
        _dup_bg = max(1, min(_dup_bg, 8))
        self._duplicate_background_repair_sem: asyncio.Semaphore = asyncio.Semaphore(_dup_bg)
        self._exploration_shadow_context_lock = asyncio.Lock()
        self._exploration_shadow_context: Optional[Dict[str, Any]] = None

        self._pg_table_name: Optional[str] = None
        self._pg_chat_id: Optional[str] = None
        # ✅ 학습/DB 저장 토글
        # - enable_db_save: MariaDB(LEARN_LIST) 등록 여부
        # - enable_learning: PG 학습(청크/임베딩) 및 (옵션) MariaDB status/chunk 반영 여부
        #
        # 운영에서 env 주입 누락이 잦아, 기본값을 "ON"으로 둔다.
        # 필요 시 env로 언제든 OFF 가능:
        # - BOARD_CONTENT_ENABLE_DB_SAVE=0
        # - BOARD_CONTENT_ENABLE_LEARNING=0
        self.enable_db_save: bool = str(os.getenv("BOARD_CONTENT_ENABLE_DB_SAVE", "1")).strip().lower() in ("1", "true", "yes", "on")
