    # 9️⃣ 용인시 공공체육시설 통합예약 전용 추출
    def _extract_yongin_publicsports_title(self, soup: BeautifulSoup) -> str:
        """
        용인시 공공체육시설 통합예약 상세 제목 추출.
        실제 제목은 `.p-table__subject_text`에 위치한다.
        """
        selectors = (
            "tr.p-table__subject .p-table__subject_text",
            ".p-table__subject .p-table__subject_text",
            ".p-table__subject_text",
            "tr.p-table__subject td",
            ".p-table__subject td",
        )
        for sel in selectors:
            try:
                el = soup.select_one(sel)
            except Exception:
                el = None
            if not el:
                continue
            try:
                txt = re.sub(r"\s+", " ", (el.get_text(" ", strip=True) or "")).strip()
            except Exception:
                txt = ""
            if txt and txt != "시설현황":
                return txt
        return "제목 없음"

    # 9️⃣ 용인도시공사 전용 추출
    def _extract_yuc_title(self, soup: BeautifulSoup) -> str:
        """
        용인도시공사(yuc.co.kr) 페이지 전용 제목 추출
        """

        # 1️⃣ og:title
        try:
            og = soup.select_one("meta[property='og:title']")
            if og and og.get("content"):
                return og["content"].strip()
        except Exception:
            pass
        
        # 2️⃣ 표 형태(table)의 상세페이지에서 제목 열을 찾아 텍스트를 추출합니다. (추가된 로직)
        try:
            # '제목' 텍스트를 포함한 th 태그를 탐색합니다.
            title_th = soup.find("th", string=re.compile(r"제목"))
            if title_th:
                # th 태그 바로 옆에 위치한 td 태그의 내용을 가져옵니다.
                title_td = title_th.find_next_sibling("td")
                if title_td:
                    return title_td.get_text(" ", strip=True) # 추출한 제목 반환
        except Exception:
            pass
        
        # 2️⃣ 게시판/콘텐츠 제목 (이미지 구조 기반 최적화)
        selectors = [
            ".article_subject", # 이미지에서 확인된 실제 제목 클래스
            "h2.article_subject", 
            "h3.tit",
            "h4.tit",
            "div.board-view h3",
            "div.sub-title h3",
        ]

        for sel in selectors:
            try:
                tag = soup.select_one(sel)
                if tag and tag.get_text(strip=True):
                    return tag.get_text(" ", strip=True)
            except Exception:
                pass

        # 3️⃣ 일반 헤더 fallback
        for sel in ["h1", "h2", "h3"]:
            try:
                tag = soup.select_one(sel)
                if tag and tag.get_text(strip=True):
                    return tag.get_text(" ", strip=True)
            except Exception:
                pass

        # 4️⃣ <title> fallback
        try:
            if soup.title and soup.title.string:
                return soup.title.string.strip()
        except Exception:
            pass

        return "제목 없음"
    # 🔟 광화문광장 전용 추출 
    def _extract_ghm_title(self, soup: BeautifulSoup) -> str:
        """
        광화문광장(gwanghwamun.seoul.go.kr) 페이지 전용 제목 추출
        """
        # 1️⃣ [게시판 형태] 이미지에서 확인된 가장 확실한 제목 태그
        # h1.view_tit는 브레드크럼 영역이 아닌 본문 헤더에만 존재함
        board_title = soup.select_one(".board_view_top h1.view_tit")
        if board_title:
            return board_title.get_text(" ", strip=True) # 게시판 제목 반환

        # 2️⃣ [이벤트 형태] 이미지에서 확인된 이벤트명 클래스
        # .event-view 내부에 있는 명확한 제목 영역만 타겟팅
        event_title = soup.select_one(".event-view .event-name")
        if event_title:
            return event_title.get_text(" ", strip=True) # 이벤트 제목 반환

        selectors = [
            ".event-name",             # 이벤트 상세페이지의 핵심 제목 (이미지 1번 구조)
            "h1.view_tit",             # 게시판 상세페이지의 핵심 제목 (이미지 2번 구조)
            ".view_tit",               # 게시판 제목 클래스 단독 탐색
            ".event-view .event-name", # 상세 페이지 계층 구조 반영
            "h2.tit",                  # 일반적인 상세페이지 타이틀 패턴
        ]

        for sel in selectors:
            try:
                tag = soup.select_one(sel) # 설정된 셀렉터로 태그 탐색
                if tag and tag.get_text(strip=True):
                    return tag.get_text(" ", strip=True) # 텍스트 정리 후 제목 반환
            except Exception:
                pass

        # 3️⃣ 일반 헤더(h2, h3)를 통한 Fallback 시도
        for sel in ["h1", "h2", "h3"]:
            try:
                tag = soup.select_one(sel) # 상위 헤더 태그 탐색
                if tag and tag.get_text(strip=True):
                    return tag.get_text(" ", strip=True) # 텍스트 정리 후 반환
            except Exception:
                pass

        # 4️⃣ [메타 데이터] 브레드크럼 노이즈가 없는 og:title 확인
        try:
            og = soup.select_one("meta[property='og:title']")
            if og and og.get("content"):
                # 사이트명만 적힌 경우를 제외하고 유효한 경우만 반환
                title_val = og["content"].strip()
                if title_val != "광화문광장":
                    return title_val
        except Exception:
            pass

        # 4️⃣ 최종 수단으로 <title> 태그의 텍스트를 가져옵니다.
        try:
            if soup.title and soup.title.string:
                return soup.title.string.strip() # 브라우저 타이틀 반환
        except Exception:
            pass

        return "제목 없음" # 모든 시도 실패 시 기본값 반환
    # 1️⃣ 국립생태원 전용 추출 
    def _extract_nie_title(self, soup: BeautifulSoup) -> str:
        """
        국립생태원(nie.re.kr) 게시판 및 생태백과 전용 제목 추출
        """
        # 1️⃣ [게시판 구조] 공지사항 등 일반 게시글 제목 (.subject)
        nie_subject = soup.select_one(".board-view__info p.subject")
        if nie_subject and nie_subject.get_text(strip=True):
            return nie_subject.get_text(" ", strip=True) # 카테고리 포함 제목 반환

        # 2️⃣하위 span(학명)을 제외하고 p 태그 안의 국문 명칭만 정확히 추출합니다.
        nie_nature_title = soup.select_one(".board-view2 .title p")
        if nie_nature_title and nie_nature_title.get_text(strip=True):
            return nie_nature_title.get_text(strip=True) # '아카치아 플로리분다' 추출

        # 3️⃣ [기타] 클래스 기반 단독 탐색
        for sel in ["p.subject", ".view_tit", "h2.tit"]:
            tag = soup.select_one(sel)
            if tag and tag.get_text(strip=True):
                return tag.get_text(" ", strip=True)
                
        # 4️⃣ [메타 데이터] og:title 활용 (사이트명 제외)
        og = soup.select_one("meta[property='og:title']")
        if og and og.get("content"):
            val = og["content"].strip()
            if val and val != "국립생태원":
                return val

        return "제목 없음"
    # 1️⃣ 국립국제교육원 전용 추출 
    def _extract_niied_eec_data_title(self, soup: BeautifulSoup) -> str:
        """
        국립국제교육원 eec-data 상세 전용(remt 등 /eec-data/ 하위 경로 포함):
        #content .article .board-view-box h3.board-title2(또는 board-ttl2) 및 본문 메타 앞 텍스트 등.
        """
        import re
        from html import unescape

        def _norm(text: str) -> str:
            t = unescape((text or "").strip())
            t = re.sub(r"[\u00A0\t\r\n]+", " ", t)
            t = re.sub(r"\s+", " ", t).strip()
            return t.strip("·|｜-–—:：「」『』<>")

        def _looks_like_file_name(text: str) -> bool:
            s = _norm(text).lower()
            if not s:
                return True
            if s in {"pdf", "doc", "docx", "hwp", "hwpx", "xls", "xlsx", "ppt", "pptx", "zip"}:
                return True
            if re.search(r"\.(pdf|docx?|hwpx?|xlsx?|pptx?|zip|rar)$", s):
                return True
            return False

        # 1) 타이틀 태그 우선(board-title2/board-title, 일부 페이지는 board-ttl2 표기)
        for sel in (
            "#content .article .board-view-box h3.board-title2",
            ".article .board-view-box h3.board-title2",
            ".board-view-box h3.board-title2",
            "h3.board-title2",
            "#content .article .board-view-box h3.board-ttl2",
            ".article .board-view-box h3.board-ttl2",
            ".board-view-box h3.board-ttl2",
            "h3.board-ttl2",
            "#content .article .board-view-box h3.board-title",
            ".article .board-view-box h3.board-title",
            ".board-view-box h3.board-title",
            "h3.board-title",
        ):
            try:
                el = soup.select_one(sel)
            except Exception:
                el = None
            if not el:
                continue
            txt = _norm(el.get_text(" ", strip=True))
            if len(txt) >= 2 and not _looks_like_file_name(txt):
                return txt

        # 2) 본문 상단에서 작성자/조회수/작성일 앞까지를 제목으로 사용
        for sel in (
            "#content .article .board-content",
            ".article .board-content",
            ".board-content",
            "#content .article",
            ".board-view-box",
        ):
            try:
                el = soup.select_one(sel)
            except Exception:
                el = None
            if not el:
                continue
            txt = _norm(el.get_text(" ", strip=True))
            if not txt:
                continue
            m = re.search(r"^(.*?)\s*(?:작성자|조회수|작성일)\b", txt)
            if m:
                title = _norm(m.group(1))
                if len(title) >= 2 and not _looks_like_file_name(title):
                    return title

        # 3) 제목 영역 내부 이미지 alt/title 폴백
        for sel in (
            "#content .article .board-view-box h3.board-title2 img",
            ".article .board-view-box h3.board-title2 img",
            ".board-view-box h3.board-title2 img",
            "h3.board-title2 img",
            "#content .article .board-view-box h3.board-ttl2 img",
            ".article .board-view-box h3.board-ttl2 img",
            ".board-view-box h3.board-ttl2 img",
            "h3.board-ttl2 img",
            "#content .article .board-view-box h3.board-title img",
            ".article .board-view-box h3.board-title img",
            ".board-view-box h3.board-title img",
            "h3.board-title img",
            ".board-view-box img",
            ".article img",
        ):
            try:
                img = soup.select_one(sel)
            except Exception:
                img = None
            if not img:
                continue
            for attr in ("alt", "title"):
                raw = (img.get(attr) or "").strip()
                val = _norm(raw)
                if len(val) >= 2 and not _looks_like_file_name(val):
                    return val

        # 4) 이미지가 감싸진 앵커/title 속성 폴백
        try:
            for tag in soup.select(".board-view-box a[title], .article a[title], #content a[title]"):
                val = _norm(tag.get("title") or "")
                if len(val) >= 2 and not _looks_like_file_name(val):
                    return val
        except Exception:
            pass

        return "제목 없음"
    def _extract_niied_eec_gallery_title(self, soup: BeautifulSoup) -> str:
        """
        국립국제교육원 eec-gallery 상세 전용:
        본문 상단의 실제 게시글 제목을 우선 추출한다.
        """
        import re
        from html import unescape

        def _norm(text: str) -> str:
            t = unescape((text or "").strip())
            t = re.sub(r"[\u00A0\t\r\n]+", " ", t)
            t = re.sub(r"\s+", " ", t).strip()
            return t.strip("·|｜-–—:：「」『』<>")

        def _looks_like_body_label(text: str) -> bool:
            s = _norm(text)
            if not s:
                return True
            # 본문 불릿/항목(ㅇ 기간/장소/대상/내용) 오검출 방지
            if re.match(r"^ㅇ\s*(기간|장소|대상|내용)\s*:", s):
                return True
            if s.startswith("기간:") or s.startswith("장소:") or s.startswith("대상:") or s.startswith("내용:"):
                return True
            return False

        # 1) 상세 타이틀 영역 우선 (gallery/notice는 board-title2를 쓰는 케이스가 많음)
        for sel in (
            "#content .article .board-view-box h3.board-title2",
            ".article .board-view-box h3.board-title2",
            ".board-view-box h3.board-title2",
            "h3.board-title2",
            "#content .article .board-view-box h3.board-title",
            ".article .board-view-box h3.board-title",
            ".board-view-box h3.board-title",
            "h3.board-title",
        ):
            try:
                el = soup.select_one(sel)
            except Exception:
                el = None
            if not el:
                continue
            txt = _norm(el.get_text(" ", strip=True))
            if len(txt) >= 2 and not _looks_like_body_label(txt):
                return txt

        # 2) 본문에서 "작성자/조회수/작성일" 메타 앞 텍스트를 제목으로 사용
        for sel in (
            "#content .article .board-content",
            ".article .board-content",
            ".board-content",
            "#content .article",
            ".board-view-box",
        ):
            try:
                el = soup.select_one(sel)
            except Exception:
                el = None
            if not el:
                continue
            txt = _norm(el.get_text(" ", strip=True))
            if not txt:
                continue

            m = re.search(r"^(.*?)\s*(?:작성자|조회수|작성일)\b", txt)
            if m:
                title = _norm(m.group(1))
                if len(title) >= 2 and not _looks_like_body_label(title):
                    return title

            # 메타 키워드가 붙지 않은 경우 문장 첫 구간을 제목 후보로 사용
            lead = re.split(r"\s{2,}|[|]|(?:\s+ㅇ\s+)", txt, maxsplit=1)[0]
            lead = _norm(lead)
            if len(lead) >= 8 and "국립국제교육원" not in lead and not _looks_like_body_label(lead):
                return lead

        # 3) 이미지 제목 폴백(일부 갤러리 케이스)
        for sel in (".board-content img", ".article img", ".board-view-box img"):
            try:
                img = soup.select_one(sel)
            except Exception:
                img = None
            if not img:
                continue
            for attr in ("alt", "title"):
                raw = (img.get(attr) or "").strip()
                val = _norm(raw)
                if len(val) >= 2:
                    return val

        return "제목 없음"
    def _extract_niied_eec_rcrut_title(self, soup: BeautifulSoup) -> str:
        """
        국립국제교육원 eec-rcrut 상세 전용:
        채용 공고 제목을 h3/본문 상단에서 안정적으로 추출한다.
        """
        import re
        from html import unescape

        def _norm(text: str) -> str:
            t = unescape((text or "").strip())
            t = re.sub(r"[\u00A0\t\r\n]+", " ", t)
            t = re.sub(r"\s+", " ", t).strip()
            return t.strip("·|｜-–—:：「」『』<>")

        # 1) 상세 타이틀 영역 우선
        for sel in (
            "#content .article .board-view-box h3.board-title2",
            ".article .board-view-box h3.board-title2",
            ".board-view-box h3.board-title2",
            "h3.board-title2",
            "#content .article .board-view-box h3.board-title",
            ".article .board-view-box h3.board-title",
            ".board-view-box h3.board-title",
            "h3.board-title",
            ".board-view-head .title",
            ".board-view-title h2",
            ".board-view-title h3",
        ):
            try:
                el = soup.select_one(sel)
            except Exception:
                el = None
            if not el:
                continue
            txt = _norm(el.get_text(" ", strip=True))
            if len(txt) >= 2:
                return txt

        # 2) 본문 상단 텍스트에서 메타(작성자/조회수/작성일) 앞까지를 제목으로 사용
        for sel in (
            "#content .article .board-content",
            ".article .board-content",
            ".board-content",
            "#content .article",
        ):
            try:
                el = soup.select_one(sel)
            except Exception:
                el = None
            if not el:
                continue
            txt = _norm(el.get_text(" ", strip=True))
            if not txt:
                continue
            m = re.search(r"^(.*?)\s*(?:작성자|조회수|작성일)\b", txt)
            if m:
                title = _norm(m.group(1))
                if len(title) >= 2:
                    return title

        return "제목 없음"
    def _extract_niied_title(self, soup: BeautifulSoup, url: str = "", html: str = "") -> str:
        """
        국립국제교육원(niied.go.kr) 게시판·공지 상세 전용 제목 추출.
        상세 본문은 #content > .article > .board-view-box > h3.board-title 구조(niied_media 등).
        표 «제목» 행·메타는 폴백.
        """
        import re
        from html import unescape

        def _norm(text: str) -> str:
            t = unescape((text or "").strip())
            t = re.sub(r"[\u00A0\t\r\n]+", " ", t)
            t = re.sub(r"\s+", " ", t).strip()
            # [] ()는 [인터뷰], [공지] 등 본문 제목에 쓰이므로 잘리지 않게 제외
            t = t.strip("·|｜-–—:：「」『』<>")
            return t

        def _split_leading_title(t: str) -> str:
            s = _norm(t)
            if not s:
                return ""
            for sep in (" | ", " - ", " :: ", " – ", " — ", " · ", " / "):
                if sep in s:
                    parts = [p.strip() for p in s.split(sep) if p.strip()]
                    if len(parts) >= 2 and len(parts[0]) >= 2:
                        return parts[0]
            return s

        def _is_breadcrumb_title(t: str) -> bool:
            s = _norm(t)
            if not s:
                return True
            if re.search(r"[가-힣]\s*>\s*[가-힣]", s) and ("상세" in s or len(s) <= 40):
                if "인터뷰" not in s and "공지" not in s and "[" not in s:
                    return True
            return False

        def _looks_like_file_name(t: str) -> bool:
            s = _norm(t).lower()
            if not s:
                return True
            if s in {"pdf", "doc", "docx", "hwp", "hwpx", "xls", "xlsx", "ppt", "pptx", "zip"}:
                return True
            if re.fullmatch(r"[a-z0-9._-]{1,80}\.(pdf|docx?|hwpx?|xlsx?|pptx?|zip|rar)", s):
                return True
            return False

        _noise_exact = {
            "홈",
            "메인",
            "ERROR",
            "404",
            "국립국제교육원",
            "국립국제교육원 글로벌역량지원센터",
            "NIIED",
        }

        # eec-data 패턴(remt/view 등): 제목이 이미지인 케이스 우선 처리
        try:
            if url and "eec-data" in (url or "").lower():
                eec_title = self._extract_niied_eec_data_title(soup)
                if eec_title and eec_title != "제목 없음":
                    return eec_title
        except Exception:
            pass

        try:
            if url and "eec-gallery" in (url or "").lower():
                gallery_title = self._extract_niied_eec_gallery_title(soup)
                if gallery_title and gallery_title != "제목 없음":
                    return gallery_title
        except Exception:
            pass

        try:
            if url and "eec-rcrut" in (url or "").lower():
                rcrut_title = self._extract_niied_eec_rcrut_title(soup)
                if rcrut_title and rcrut_title != "제목 없음":
                    return rcrut_title
        except Exception:
            pass

        # eec-notice: 공지 상세는 h3.board-title2 등으로 마크업이 달라 사이트명(og:title)으로 떨어지는 경우가 있음.
        # 갤러리와 동일하게 본문 상단 «작성자/조회수/작성일» 앞 텍스트를 제목으로 우선 사용.
        try:
            if url and "eec-notice" in (url or "").lower():
                notice_title = self._extract_niied_eec_gallery_title(soup)
                if notice_title and notice_title != "제목 없음":
                    return notice_title
        except Exception:
            pass

        try:
            for sel in (
                "#content .article .board-view-box h3.board-title2",
                "#content .board-view-box h3.board-title2",
                ".article .board-view-box h3.board-title2",
                ".board-view-box h3.board-title2",
                "h3.board-title2",
                "#content .article .board-view-box h3.board-title",
                "#content .board-view-box h3.board-title",
                ".article .board-view-box h3.board-title",
                ".board-view-box h3.board-title",
                "h3.board-title",
                ".board-view-head .title",
                ".board-view-head h2",
                ".board-view-head h3",
                ".board-view-title h2",
                ".board-view-title h3",
                ".board_view_title",
                ".board-view-title",
                ".bd_view .subject",
                ".bbs_view .subject",
                ".article-head .title",
                ".article-title",
                ".view_title",
                ".view-title",
                ".bbs_tit",
                ".bbs-tit",
                "#contents .content_title",
                "#contents h2.tit",
                ".con_box .tit",
                "div.article-head h2",
                "h2.view-title",
                "h3.tit",
            ):
                el = soup.select_one(sel)
                if not el:
                    continue
                txt = _norm(el.get_text(" ", strip=True))
                if (
                    len(txt) < 2
                    or txt in _noise_exact
                    or _is_breadcrumb_title(txt)
                    or _looks_like_file_name(txt)
                ):
                    continue
                return txt

            label_re = re.compile(r"^\s*(제목|글제목|공고명)\s*$")
            for th in soup.find_all("th"):
                if not label_re.match(th.get_text(" ", strip=True) or ""):
                    continue
                td = th.find_next_sibling("td")
                if not td and th.parent and th.parent.name == "tr":
                    td = th.parent.find("td")
                if td:
                    txt = _norm(td.get_text(" ", strip=True))
                    if len(txt) >= 2 and not _looks_like_file_name(txt):
                        return txt

            og = soup.select_one("meta[property='og:title']")
            if og and og.get("content"):
                val = _split_leading_title(og["content"])
                if (
                    val
                    and val not in _noise_exact
                    and len(val) >= 2
                    and not _is_breadcrumb_title(val)
                    and not _looks_like_file_name(val)
                ):
                    return _norm(val)

            if soup.title and soup.title.string:
                val = _split_leading_title(soup.title.string)
                if (
                    val
                    and val.upper() not in ("ERROR", "404")
                    and val not in _noise_exact
                    and not _is_breadcrumb_title(val)
                    and not _looks_like_file_name(val)
                ):
                    if len(val) >= 2:
                        return _norm(val)
        except Exception:
            pass

        try:
            if html:
                fb = _extract_web_title_from_html(html, url=url or "")
                if fb:
                    val = _split_leading_title(fb)
                    if (
                        val
                        and val not in _noise_exact
                        and len(val) >= 2
                        and not _is_breadcrumb_title(val)
                        and not _looks_like_file_name(val)
                    ):
                        return _norm(val)
        except Exception:
            pass

        return "제목 없음"

    def _extract_epik_title(self, soup: BeautifulSoup) -> str:
        """
        EPIK(epik.go.kr, 원어민보조교사선발) Updates 상세: .upd-detail-box > h5.h5-tit2
        """
        import re
        from html import unescape

        def _norm(text: str) -> str:
            t = unescape((text or "").strip())
            t = re.sub(r"[\u00A0\t\r\n]+", " ", t)
            return re.sub(r"\s+", " ", t).strip()

        try:
            el = soup.select_one(".upd-detail-box h5.h5-tit2") or soup.select_one("div.upd-detail-box > h5")
            if el:
                txt = _norm(el.get_text(" ", strip=True))
                if len(txt) >= 2:
                    return txt
        except Exception:
            pass
        return "제목 없음"
    # 1️⃣ 춘천시청 전용 추출 
    def _extract_chuncheon_title(self, soup: BeautifulSoup, url: str = "") -> str:
        """
        춘천시청(chuncheon.go.kr) 모든 게시판 및 상세페이지 유형에 최적화된 강화된 제목 추출
        """
        import re
        from html import unescape

        # 1. 텍스트 내 노이즈(새창, 신규 아이콘, 특수공백 등)를 제거하는 내부 함수
        def _clean(t: str) -> str:
            if not t: return ""
            t = unescape(t) # HTML 특수문자(&nbsp; 등)를 일반 문자로 변환
            t = re.sub(r"[\u00A0\t\r\n]+", " ", t) # 특수 공백 및 줄바꿈을 일반 공백으로 단일화
            t = re.sub(r"\[(새창|신규|N)\]|\b(새창|신규)\b", "", t, flags=re.I) # 제목 내부의 불필요한 말머리 노이즈 제거
            t = re.sub(r"\s+", " ", t).strip() # 연속된 모든 공백을 하나로 합치고 앞뒤 공백 제거
            # 제목 자체의 괄호 정보(예: 공고번호)는 보존하고, 구분자/노이즈 기호만 제거
            return t.strip("·|｜-–—:：[]<>") # 제목 시작과 끝에 붙은 불필요한 특수문자 정리

        # 계약정보공개 상세: 구분 + 계약명 (chuncheon_contract.extract_contract_display_title)
        lu = (url or "").lower()
        if "chuncheon.go.kr/contract/" in lu and ("/detail/" in lu or "ctrtacctbookmngno=" in lu):
            try:
                cn = _extract_chuncheon_contract_display_title(soup, url or "")
                if cn:
                    return _clean(cn)
            except Exception:
                pass

        # 2. 이미지 구조 기반 핵심 제목 선택자 (정확도 순서로 배치 및 강화)
        title_selectors = [
            "#not_ancmt_sj",                      # 시청 공고: 특정 ID 기반 (image_ffdc7b)
            ".boardview-tit",                     # 공통 제목 클래스 단독
            ".board-view-top h2",                 # 시장실/현장스케치 제목 (image_fe7804 확인됨)
            ".common-community .notice-tit h3",   # 기업지원 상세: 명확한 계층 구조 (image_ff02ff 추가)
            ".notice-tit h3",                     # 기업지원: .notice-tit > h3 구조 (image_ff6fa6)
            ".boardview-top .boardview-tit",      # 소식지/이벤트: .boardview-tit 구조 (image_004d38)
            ".view-tit .boardview-tit",           # 공고: 계층형 구조 (image_004d7c)
            ".boardview .sub-tit h3",             # 관광: .sub-tit > h3 구조 (image_0050fe)
            ".sub-tit h3",                        # 일반 서브 타이틀 범용
            "h3.view_tit",                        # 표준 게시판 제목 클래스
            "#print-wrap h3",                     # 본문 영역(print-wrap) 내 제목 (범용성 강화)
            "h2.tit",                             # 일반 페이지 상단 헤더
        ]

        # 2-1. 채용정보 상세 고정 구조 우선 처리
        # - chuncheon_job: 모든 listview·li.half 내 (채용제목/제목) 라벨-값 쌍에서 제목 추출
        try:
            jt = _extract_chuncheon_job_title_from_soup(soup)
            if jt:
                cleaned_text = _clean(jt)
                if cleaned_text and len(cleaned_text) > 2 and cleaned_text not in ["담당자정보", "상세정보", "관련자료"]:
                    return cleaned_text
        except Exception:
            pass
        
        # 3. 설정된 선택자들을 순회하며 가장 적절한 제목 텍스트 추출 시도
        for sel in title_selectors:
            tag = soup.select_one(sel)
            if tag:
                cleaned_text = _clean(tag.get_text(" ", strip=True))
                # 추출된 텍스트가 소제목(담당자정보 등)이 아닌 진짜 제목인지 검증
                if cleaned_text and len(cleaned_text) > 2 and cleaned_text not in ["담당자정보", "상세정보", "관련자료"]:
                    return cleaned_text

        # 4. 표(Table) 또는 리스트 형태에서 '제목' 라벨을 찾아 데이터 추출 (폴백)
        try:
            # th, p, span 태그 중 '제목'이라는 텍스트가 포함된 요소를 탐색
            label_tag = soup.find(lambda t: t.name in ["th", "p", "span", "dt"] and 
                                any(x in t.get_text() for x in ["채용제목", "제목", "강좌명"]))
            if label_tag:
                # 라벨 요소의 바로 다음 데이터 영역(td, dd 등)에서 텍스트 추출
                target_td = label_tag.find_next(["td", "p", "dd", "span"])
                if target_td:
                    cleaned_td = _clean(target_td.get_text(" ", strip=True))
                    if cleaned_td: return cleaned_td
        except Exception:
            pass

        # 5. 메타 데이터(SNS 공유용 제목)에서 제목 확보
        for meta_sel in ["meta[property='og:title']", "meta[name='title']", "[itemprop='headline']"]:
            meta_tag = soup.select_one(meta_sel)
            if meta_tag:
                val = _clean(meta_tag.get("content") or meta_tag.get_text())
                if val and "춘천시청" != val and len(val) > 2: # 사이트명만 있는 경우 제외
                    return val

        # 6. 최종 수단: 브라우저 상단 타이틀에서 사이트 정보 제거 후 추출
        if soup.title and soup.title.string:
            t = _clean(soup.title.string)
            # '-', '|', '｜' 등의 구분자를 기준으로 앞부분(순수 제목)만 분리
            return re.split(r"\s*(?:-|\||｜)\s*", t)[0].strip()

        return "제목 없음" # 모든 시도가 실패했을 때 반환할 기본값
    # 1️⃣ 충남청년포털 전용 추출
    def _extract_chungnam_youth_title(self, soup: BeautifulSoup) -> str:
        """
        충남청년포털(youth.chungnam.go.kr) 상세:
        - 공지/게시판(/bbs/...): .sInner 직계 h5
        - 청년 공간정보(/youthSpaceInfo/.../view): .thum_desc .sub_tit h4 (섹션명은 .sInner > h3)
        - 맞춤형 청년정책(/customSupp/.../view): .sInner 직계 h3
        """
        import re
        from html import unescape

        def _clean(t: str) -> str:
            if not t:
                return ""
            t = unescape(str(t))
            t = re.sub(r"[\u00A0\t\r\n]+", " ", t)
            t = re.sub(r"\s+", " ", t).strip()
            return t

        for sel in (
            "#container .content_in_wrap .sInner > h5",
            ".content_in_wrap .sInner > h5",
            "#container .content_in_wrap .sInner h5",
            "#container .content_in_wrap .sInner .cif_spc_box .thum_desc .sub_tit h4",
            ".cif_spc_box .thum_desc .sub_tit h4",
            ".thum_desc .sub_tit h4",
            "#container .content_in_wrap .sInner > h3",
            "#container .sInner > h3",
            ".content_in_wrap .sInner > h3",
            "#container .content_in_wrap .sInner h3",
        ):
            el = soup.select_one(sel)
            if el:
                txt = _clean(el.get_text(" ", strip=True))
                if txt and len(txt) > 1:
                    return txt

        try:
            for li in soup.select("ul li, dl"):
                label = li.find(["span", "dt", "th", "strong"])
                if not label:
                    continue
                if re.sub(r"\s+", "", label.get_text("", strip=True) or "") != "정책명":
                    continue
                nxt = label.find_next_sibling(["dd", "td", "span", "div"])
                if nxt:
                    v = _clean(nxt.get_text(" ", strip=True))
                    if v and len(v) > 1:
                        return v
        except Exception:
            pass

        return "제목 없음"

    def _extract_gachi_chungbuk_title(self, soup: BeautifulSoup) -> str:
        """
        충북가치자람(gachi.chungbuk.go.kr)
        - 게시판 상세(/bbs/.../view.do): `.notice_view .tit_wrap h3`
        - 지원사업·정책 상세(/portal/policy/...): `.support_main .tit_wrap h2`
        """
        import re
        from html import unescape

        def _clean(t: str) -> str:
            if not t:
                return ""
            t = unescape(str(t))
            t = re.sub(r"[\u00A0\t\r\n]+", " ", t)
            t = re.sub(r"\s+", " ", t).strip()
            return t

        for sel in (
            "#go_content .notice_view .tit_wrap h3",
            ".notice_view .tit_wrap h3",
            "#go_content .support_main .tit_wrap h2",
            ".support_area .support_main .tit_wrap h2",
            ".support_main .tit_wrap h2",
        ):
            el = soup.select_one(sel)
            if el:
                txt = _clean(el.get_text(" ", strip=True))
                if txt and len(txt) > 1:
                    return txt
        return ""

    # 1️⃣ 동작구청 전용 추출
    def _extract_dongjak_title(self, soup: BeautifulSoup, url: str = "") -> str:
        import re
        from html import unescape

        try:
            from backend.board.dongjak_board import extract_dongjak_title

            title = extract_dongjak_title(soup, url=url)
            if title:
                return title
        except Exception:
            pass

        def _clean(t: str) -> str:
            if not t: return ""
            t = unescape(t)
            t = re.sub(r"[\u00A0\t\r\n]+", " ", t)
            t = re.sub(r"\s+", " ", t).strip()
            return t.strip("·|｜-–—:：")

        def _is_noise_title_text(t: str) -> bool:
            v = _clean(t)
            if not v:
                return True
            # 공연명/도서명 등에서 <...> 표기가 실제 제목 일부로 쓰일 수 있다.
            # HTML 태그로 보이는 경우만 노이즈로 간주한다.
            if re.search(r"<\s*/?\s*[a-zA-Z!][^>]{0,80}>", v):
                return True
            if "포털사이트" in v:
                return True
            if v in noise_titles:
                return True
            if v in {"공지사항", "민원사무서식", "관련사이트", "자료관리담당", "최종업데이트"}:
                return True
            return False

        # 제목으로 채택하지 않을 명백한 메뉴/네비게이션 단어
        noise_titles = {
            "분야별정보", "분야별 정보", "홈", "상세보기", "동작구청", 
            "게시물 상세", "본문 시작", "생활정보", "행정정보", "목록"
        }

        # --- [최우선] 학술연구용역결과 등 B0001371: 본문 dl에서 라벨「용역명」의 dd ---
        u_chk = (url or "").lower()
        if "b0001371" in u_chk.replace("_", ""):
            try:
                root = (
                    soup.select_one(".nw-txbx .view.mb20")
                    or soup.select_one("#contentDiv .view.mb20")
                    or soup.select_one("#contentDiv.nw-content-data")
                    or soup.select_one("#contentDiv")
                    or soup.select_one(".nw-content-data")
                )
                for dt in (root.find_all("dt") if root else soup.find_all("dt")):
                    if re.sub(r"\s+", "", dt.get_text(" ", strip=True) or "") != "용역명":
                        continue
                    dd = dt.find_next_sibling("dd")
                    if dd:
                        val = _clean(dd.get_text(" ", strip=True))
                        if val and val not in noise_titles:
                            return val
            except Exception:
                pass

        # --- 공공건축공사현황 등 B0000373: #contentDiv/.nw-txbx .view .table > p.heading ---
        if "b0000373" in u_chk.replace("_", ""):
            try:
                heading_el = (
                    soup.select_one("#contentDiv .nw-txbx .view .table p.heading")
                    or soup.select_one(".nw-txbx .view .table p.heading")
                    or soup.select_one(".nw-content-data .view .table p.heading")
                    or soup.select_one("#contentDiv .view .table p.heading")
                    or soup.select_one("#contentDiv p.heading")
                    or soup.select_one(".nw-content-data p.heading")
                )
                if heading_el:
                    val = _clean(heading_el.get_text(" ", strip=True))
                    if val and val not in noise_titles:
                        return val
            except Exception:
                pass

        # --- [우선순위 1] 데이터 원본 태그 (image_8e8bd8 기반) ---
        # script 태그 내에 data-name 속성으로 제목이 명시된 경우 (가장 확실함)
        if "b0001406" in u_chk.replace("_", "") or "viewtype=body" in u_chk:
            for sel in (
                ".acview-tbox .btit",
                ".acview-top .acview-tbox .btit",
                "#acv-contents .btit",
            ):
                try:
                    title_el = soup.select_one(sel)
                except Exception:
                    title_el = None
                if not title_el:
                    continue
                val = _clean(title_el.get_text(" ", strip=True))
                if val and not _is_noise_title_text(val):
                    return val

        script_data = soup.select_one("script#fileName")
        if script_data and script_data.get("data-name"):
            val = _clean(script_data.get("data-name"))
            if val and val not in noise_titles:
                return val

        # --- [우선순위 2] 고유 데이터 속성 (image_8e8bd8, 8f1e60 기반) ---
        # h2 태그 중 data-brl-prop 속성이 'style:sub-heading'인 경우
        prop_header = soup.select_one("h2[data-brl-prop='style:sub-heading']")
        if prop_header:
            txt = _clean(prop_header.get_text(" ", strip=True))
            if txt and not _is_noise_title_text(txt):
                return txt

        # --- [우선순위 2.5] 본문 루트 헤딩 기반 ---
        # 동작구 부서안내(deptGdc.do) 등에서 실제 제목이 #contentDiv h2에 들어오며,
        # <title>은 breadcrumb(… < 포털사이트)인 경우가 많다.
        # 장바구니 물가정보 등 list.do 상세는 #contentDiv .nw-txbx > h3 에 실제 제목이 들어온다.
        for sel in (
            "#contentDiv .nw-txbx > h3",
            "#contentDiv .nw-txbx h3",
            ".nw-content-data .nw-txbx > h3",
            ".nw-content-data .nw-txbx h3",
            ".nw-txbx > h3",
            ".nw-txbx h3",
            "#contentDiv .nw-content-data .view.mb20 > p.content-txt",
            "#contentDiv .nw-content-data .view > p.content-txt",
            ".nw-content-data .view.mb20 > p.content-txt",
            ".nw-content-data .view > p.content-txt",
        ):
            try:
                h = soup.select_one(sel)
            except Exception:
                h = None
            if not h:
                continue
            txt = _clean(h.get_text(" ", strip=True))
            if txt and not _is_noise_title_text(txt):
                return txt

        # 예약 상세(view.do, tmplatSeCd=02)는 .program-reserv-wrap .subject h4에 실제 제목이 들어온다.
        for sel in (
            "form.form-inline .program-reserv-wrap .subject h4",
            ".program-reserv-wrap .subject h4",
            ".subject h4",
        ):
            try:
                h = soup.select_one(sel)
            except Exception:
                h = None
            if not h:
                continue
            txt = _clean(h.get_text(" ", strip=True))
            if txt and not _is_noise_title_text(txt):
                return txt

        for sel in (
            "#go_content #contentDiv h2",
            "#contentDiv h2",
            ".nw-content-data h2",
        ):
            try:
                h = soup.select_one(sel)
            except Exception:
                h = None
            if not h:
                continue
            txt = _clean(h.get_text(" ", strip=True))
            if txt and not _is_noise_title_text(txt):
                return txt

        # --- [우선순위 3] 히든 필드 원본 데이터 (image_8f0eff, 8f07d3 기반) ---
        # 폼 데이터에 숨겨진 제목 필드 (nttSj, not_ancmt_sj 등)
        for name in ["not_ancmt_sj", "nttSj", "sj"]:
            hidden = soup.select_one(f'input[name="{name}"], input[id="{name}"]')
            if hidden and hidden.get("value"):
                val = _clean(hidden.get("value"))
                if val and not _is_noise_title_text(val):
                    return val

        # --- [우선순위 4] 특정 클래스 기반 탐색 (image_8f12f6, 8f0eff 기반) ---
        selectors = [
            ".nw-txbx .view .subject", # 동행정 게시판 정밀 구조
            ".view .subject",          # 민원지도/민원포털 핵심 클래스
            ".view p.subject",         # 단독 p 태그 구조
            ".board_view_top h3",      # 표준 게시판 레이아웃
        ]
        for sel in selectors:
            tag = soup.select_one(sel)
            if tag:
                txt = _clean(tag.get_text(" ", strip=True))
                if txt and len(txt) > 1 and not _is_noise_title_text(txt):
                    return txt

        # --- [우선순위 5] 표(Table) 라벨 기반 추출 (업소/상가 정보 대응) ---
        try:
            # '상호', '명칭', '업소명' 등 실제 데이터 라벨 옆의 값을 채택
            label = soup.find(["th", "td", "dt"], string=re.compile(r"상호|명칭|업소명"))
            if label:
                data = label.find_next_sibling(["td", "dd"]) or label.find_next(["td", "dd"])
                if data:
                    txt = _clean(data.get_text(" ", strip=True))
                    if txt and not _is_noise_title_text(txt):
                        return txt
        except Exception:
            pass

        # --- [최종 Fallback] 브라우저 타이틀 활용 ---
        if soup.title and soup.title.string:
            parts = re.split(r"\s*(?:\||｜|-)\s*", _clean(soup.title.string))
            for p in parts:
                p_clean = p.strip()
                if p_clean and not _is_noise_title_text(p_clean) and "동작구청" not in p_clean:
                    return p_clean

        return "제목 없음"
    # 🔟 밀양시청 전용 추출
    def _extract_guro_title(self, soup: BeautifulSoup, url: str = "") -> str:
        """구로구청 예약/강좌 상세 제목 추출."""
        import re

        url_low = (url or "").lower()
        if "guro.go.kr" not in url_low:
            return ""

        def _clean_title_text(value: str) -> str:
            text = re.sub(r"\s+", " ", str(value or "")).strip()
            text = re.sub(r"\s*신청자\s*:\s*\d+\s*/\s*\d+\s*명.*$", "", text, flags=re.IGNORECASE)
            text = re.sub(r"\s*대기자\s*:\s*\d+\s*/\s*\d+\s*명.*$", "", text, flags=re.IGNORECASE)
            return text.strip(" |:-")

        if "/yeyak/edclctreview.do" in url_low:
            for sel in (
                "tbody tr:first-child td:first-child",
                "table tbody tr:first-child td:first-child",
                "tbody tr:first-child td",
                "table tbody tr:first-child td",
            ):
                try:
                    node = soup.select_one(sel)
                except Exception:
                    node = None
                if not node:
                    continue
                title = _clean_title_text(node.get_text(" ", strip=True))
                if title and title not in {"< 참고사항 >", "참고사항"}:
                    return title

        return ""

    def _extract_miryang_title(self, soup: BeautifulSoup) -> str:
        """
        밀양시청(miryang.go.kr) 상세페이지 전용 제목 추출
        이미지 분석 결과:
        - 시청/관광 계열: div.headinfo > h3.BoR-h2 (또는 h2.BoR-h2)
        - 농업교육 계열: table.board_view_table th > b
        """
        import re

        def _label_table_title(scope: BeautifulSoup) -> str:
            labels = (
                "제목",
                "민원명",
                "행사명",
                "계약명",
                "사업명",
                "공사명",
                "용역명",
                "물품명",
                "교육명",
                "강좌명",
                "모집명",
            )
            flat_labels = tuple(re.sub(r"\s+", "", label) for label in labels)
            for tr in scope.select("table tr"):
                for th in tr.find_all("th"):
                    label_flat = re.sub(r"\s+", "", th.get_text(" ", strip=True))
                    if not label_flat or not any(label in label_flat for label in flat_labels):
                        continue
                    td = th.find_next_sibling("td")
                    if not td:
                        continue
                    txt = td.get_text(" ", strip=True)
                    if txt:
                        return txt
            return ""

        try:
            # 0. [밀양 농업교육 상세] board_view_table 첫 제목행의 b 태그
            for sel in (
                "table.board_view_table th[colspan] > b",
                "table.board_view_table tr:first-child th > b",
                "table.board_view_table th > b",
            ):
                agredu_title = soup.select_one(sel)
                if agredu_title:
                    t = agredu_title.get_text(" ", strip=True)
                    if t:
                        return t

            # 0. [밀양 평생학습포털 edu/clubinfo 상세] h1#b_title — 시청 메인 게시판과 다른 템플릿
            edu_club_h1 = soup.select_one("h1#b_title")
            if edu_club_h1:
                t = edu_club_h1.get_text(" ", strip=True)
                if t:
                    return t

            # 1. [이미지 303125 기반] board-view-head 내부의 제목 구조를 최우선으로 탐색합니다.
            # 기능별 1줄 주석: 이미지에서 확인된 head > title > h3 계층 구조를 정확히 타겟팅합니다.
            head_title = soup.select_one(".board-view-head .board-view-title h3")
            if head_title:
                return head_title.get_text(" ", strip=True)
                
            # 1. [리빙랩 전용] 최신 리빙랩 상세페이지의 h3 태그 탐색
            # 기능별 1줄 주석설명: 리빙랩 전용 제목 클래스인 board-view-title 내의 h3 요소를 우선 추출합니다.
            living_lab_title = soup.select_one(".board-view-title h3")
            if living_lab_title:
                return living_lab_title.get_text(" ", strip=True)

            # 1.5. 밀양 본문 헤더(.headinfo) 내 BoR-h2 제목 추출
            for sel in (
                ".inboxRead .headinfo > h3.BoR-h2",
                ".inboxRead .headinfo > h2.BoR-h2",
                ".headinfo > h3.BoR-h2",
                ".headinfo > h2.BoR-h2",
                "h3.BoR-h2",
                "h2.BoR-h2",
            ):
                bor_title = soup.select_one(sel)
                if bor_title and bor_title.get_text(strip=True):
                    # 텍스트 추출 시 내부 공백 및 개행 정리
                    return bor_title.get_text(" ", strip=True)

            # 1.6. 계약현황 등 메타 테이블에서 제목 역할을 하는 라벨-값 행 인식
            table_title = _label_table_title(soup)
            if table_title:
                return table_title

            # 3. [Fallback] 일반적인 게시판 제목 패턴 탐색
            selectors = [
                "table.board_view_table th[colspan] > b",
                "table.board_view_table tr:first-child th > b",
                "table.board_view_table th > b",
                ".board-view-title h3", # 리빙랩 재확인
                "h3.BoR-h2",
                "h2.BoR-h2",
                ".inboxRead .headinfo h3",
                ".inboxRead .headinfo h2", # 이미지 계층 구조 반영
                "h2.tit", 
                "h3.tit",
                ".view_tit"
            ]
            for sel in selectors:
                el = soup.select_one(sel)
                if el and el.get_text(strip=True):
                    return el.get_text(" ", strip=True)

        except Exception:
            # 예외 발생 시 상위 스코어링 로직으로 넘기기 위해 패스
            pass

        return "제목 없음"
    # 🔟 송파구청 전용 추출
    def _extract_songpakids_title(self, soup: BeautifulSoup) -> str:
        """
        송파어린이문화회관(songpakids.com) 상세 전용 제목.
        - 공지/아카이브 상세: .panel-heading > h4
        - 일부 템플릿: #subContent .panel-heading h4
        """
        try:
            for sel in (
                ".panel-heading > h4",
                ".panel-default .panel-heading > h4",
                "#subContent .panel-heading h4",
                ".write-form .panel-heading h4",
            ):
                el = soup.select_one(sel)
                if not el:
                    continue
                t = el.get_text(" ", strip=True)
                if t:
                    return t
        except Exception:
            pass
        return ""
    def _extract_umppa_seoul_title(self, soup: BeautifulSoup, url: str = "") -> str:
        """
        탄생육아 몽땅정보통(umppa.seoul.go.kr) 전용 제목.
        - 맞춤형정보 상세(fcltyInfoManage): .center_i_con h4
        - 구역/메뉴형: .sub-content .content-info .title-wrap h2.title (예: 서울키즈 오케이존)
        - 키즈카페 상세형: .kidscafe_title h2.sub_title01
        - 시설 상세형: .board-top .title-wrap h3.title (예: 이디야커피 학동역점)
        빈 문자열이면 상위에서 범용 제목 추출로 진행.
        """
        import re

        try:
            # 맞춤형정보 상세는 h2.sub_title01이 섹션명("맞춤형 정보 서비스")인 경우가 많아 h4를 최우선.
            if "bd_selectfcltyinfomanage.do" in (url or "").lower():
                for sel in (
                    ".center_i_con h4",
                    ".center_i_inf .center_i_con h4",
                    ".center_i_inf li .center_i_con h4",
                ):
                    el = soup.select_one(sel)
                    if el:
                        t = el.get_text(" ", strip=True)
                        if t:
                            return t

            for sel in (
                ".board-detail .board-top .title",
                ".board-top .title-wrap h3.title",
                ".board-detail .board-top .title-wrap h3.title",
                ".sub-content .board-detail .board-top h3.title",
                ".board-top .title",
            ):
                el = soup.select_one(sel)
                if el:
                    t = el.get_text(" ", strip=True)
                    if t:
                        return t

            # bordContDetail 계열은 .content-info .title-wrap h2.title가 섹션명("보도자료")인 경우가 많아
            # board-top 계열 실패 시에만 폴백으로 사용한다.
            for sel in (
                ".content-info .title-wrap h2.title",
                ".sub-content .content-info .title-wrap h2.title",
                "div.content-info.title-bg-2 .title-wrap h2.title",
                ".sub-content .title-wrap h2.title",
                ".kidscafe_title h2.sub_title01",
                ".btn.clear.mb_55.bot_init .kidscafe_title h2.sub_title01",
            ):
                el = soup.select_one(sel)
                if el:
                    t = el.get_text(" ", strip=True)
                    if t:
                        return t

            for script in soup.find_all("script"):
                st = script.string or script.get_text() or ""
                m = re.search(
                    r'document\.title\s*=\s*["\']([^"\']+)["\']',
                    st,
                    re.IGNORECASE,
                )
                if not m:
                    continue
                raw = (m.group(1) or "").strip()
                if not raw:
                    continue
                if " < " in raw:
                    head = raw.split(" < ", 1)[0].strip()
                    if head:
                        return head
                return raw
        except Exception:
            pass
        return ""
    def _extract_songpalearn_title(self, soup: BeautifulSoup) -> str:
        """
        송파런(songpa.go.kr/learn) 상세페이지 전용 제목 추출
        이미지에서 확인된 div.th, div.td 구조를 반영하여 수정함
        """
        import re

        _label_re = re.compile(r"^\s*(제목|강좌명|프로그램명)\s*$")

        try:
            # 1a. [구조 고정] li.table > div.th + div.td (table_box_ul 레이아웃)
            for li in soup.select("li.table.half, li.table"):
                th = li.find("div", class_="th", recursive=False)
                td = li.find("div", class_="td", recursive=False)
                if not th or not td:
                    continue
                if not _label_re.match(th.get_text(" ", strip=True) or ""):
                    continue
                t = td.get_text(" ", strip=True)
                if t:
                    return t

            # 1b. div.th 라벨 — string= 매칭은 공백/자식 노드에서 실패하므로 get_text로 판별
            for target_div_th in soup.select("div.th"):
                if not _label_re.match(target_div_th.get_text(" ", strip=True) or ""):
                    continue
                target_div_td = target_div_th.find_next_sibling("div", class_="td")
                if target_div_td:
                    t = target_div_td.get_text(" ", strip=True)
                    if t:
                        return t

            # 2. [게시판/강좌 상세] 표준 클래스 기반 추출
            # 기능별 1줄 주석: 기존의 h3.tit나 .board-view-header 등 게시판 형태의 제목을 탐색합니다.
            selectors = [
                ".board-view-header .title",
                "#content h3.tit",
                ".course-detail-title",
                ".view_tit",
                "h3.course_tit"
            ]
            for sel in selectors:
                el = soup.select_one(sel)
                if el and el.get_text(strip=True):
                    # '공지사항' 같은 대분류 텍스트가 걸리지 않도록 필터링이 필요할 수 있음
                    return el.get_text(" ", strip=True)

            # 3. [표 형태 데이터] 표준 th/td 태그 대응
            # 기능별 1줄 주석: div가 아닌 실제 table 태그로 구성된 경우를 대비해 th/td 구조를 검색합니다.
            target_th = soup.find("th", string=re.compile(r"제목|강좌명|프로그램명"))
            if target_th:
                target_td = target_th.find_next_sibling("td")
                if target_td:
                    return target_td.get_text(" ", strip=True)

        except Exception:
            # 기능별 1줄 주석: 오류 발생 시 시스템이 중단되지 않도록 예외를 통과시킵니다.
            pass

        return "제목 없음"
    def _extract_board_reg_date(self, soup: BeautifulSoup, html: str = "", url: str = "") -> Optional[datetime]:
        """상세 페이지에서 등록일/작성일 추출. 라벨(th/td/dt) 기반 후 extract_post_date 폴백."""
        import re

        health_info = _extract_health_seoulmc_date_writer(soup, url=url)
        if health_info.get("date"):
            try:
                dt_health = parse_date(health_info.get("date"))
                if dt_health:
                    return dt_health
            except Exception:
                pass

        if url and "pyeongtaek.go.kr" in (url or "").lower() and "/recruitanm/view.do" in (url or "").lower():
            try:
                from backend.board.pyeongtaek_board import extract_pyeongtaek_recruit_reg_date_text

                raw_pt = extract_pyeongtaek_recruit_reg_date_text(soup, url=url)
                dt_pt = parse_date(raw_pt) if raw_pt else None
                return dt_pt
            except Exception:
                return None

        if url and is_youthcenter_bbs_view_url(url):
            try:
                youthcenter_dt = extract_youthcenter_board_reg_date(soup, url=url, html=html)
                if youthcenter_dt:
                    return youthcenter_dt
            except Exception:
                pass

        if url and is_youthcenter_policy_detail_url(url):
            try:
                youthcenter_policy_dt = extract_youthcenter_policy_reg_date(soup, url=url, html=html)
                if youthcenter_policy_dt:
                    return youthcenter_policy_dt
            except Exception:
                pass

        # EPIK(영문 UI): 메타에 «등록일» 라벨 없이 .infor li.date 에만 YYYY-MM-DD
        if url and "epik.go.kr" in (url or "").lower():
            try:
                el = soup.select_one(".upd-detail-box .infor li.date") or soup.select_one(".upd-detail-box li.date")
                if el:
                    val = (el.get_text(strip=True) or "").strip()
                    if val:
                        dt = parse_date(val)
                        if dt:
                            return dt
            except Exception:
                pass

        # 서울역사박물관 기증 상세: 별도 등록일 없음 → 「기증자 소개」 본문의 기증일(YYYY년 M월 D일)을 등록일로 간주
        if url:
            try:
                from backend.board.museum_seoul_board import (
                    extract_museum_seoul_giver_reg_date_from_soup,
                    is_museum_seoul_giver_view_url,
                )

                if is_museum_seoul_giver_view_url(url):
                    intro_dt = extract_museum_seoul_giver_reg_date_from_soup(soup)
                    if intro_dt:
                        return intro_dt
            except Exception:
                pass

        # 강남구청 본청 /office/…/board/…/view.do (문화재단 등): 등록일 라벨 없이 .bbs-view .post-info span에만 YYYY-MM-DD
        if url and is_gangnam_family_url(url) and is_gangnam_main_office_board_view_url(url):
            try:
                gn_off_dt = extract_gangnam_office_board_reg_date(soup)
                if gn_off_dt:
                    return gn_off_dt
            except Exception:
                pass

        # 광명시 행사ㆍ축제 상세: 등록일 라벨이 없으므로 행사기간의 시작일을 사용한다.
        # GM festival pages may contain future event periods; do not treat those as registration dates.
        if url and is_gm_festival_detail_url(url):
            try:
                gm_festival_dt = extract_gm_festival_reg_date(soup, url=url)
                if gm_festival_dt:
                    return gm_festival_dt
            except Exception:
                pass

        # 광명시 상수도 계약사업목록 상세: 계약일자를 등록일/기준일로 사용한다.
        if url and is_gm_lobas_tcm_detail_url(url):
            try:
                gm_lobas_dt = extract_gm_lobas_tcm_reg_date(soup, url=url)
                if gm_lobas_dt:
                    return gm_lobas_dt
            except Exception:
                pass

        # 구로구청 전용 분기: URL에 guro.go.kr이 포함된 경우 전용 로직 실행
        if url and "guro.go.kr" in url:
            # 구로구청 게시판 특유의 '등록일' 라벨 태그 탐색
            guro_date_tag = soup.find(["th", "span"], string=re.compile(r"등록일"))
            if guro_date_tag:
                # 라벨 옆에 위치한 데이터 태그(td 또는 다음 span)에서 텍스트 추출
                guro_val_tag = guro_date_tag.find_next(["td", "span"])
                if guro_val_tag:
                    guro_val = guro_val_tag.get_text(strip=True)
                    # 추출된 텍스트에서 날짜 객체로 변환 시도
                    guro_dt = parse_date(guro_val)
                    if guro_dt:
                        return guro_dt
                        
        # 1) 라벨 기반: 작성일/등록일 포함 태그 → 다음 형제에서 값 추출
        for tag in soup.find_all(["th", "td", "span", "label", "dt"]):
            # 태그 내부 텍스트의 공백을 제거하여 비교 준비
            raw = (tag.get_text(strip=True) or "").strip()
            clean = re.sub(r"\s+", "", raw)
            
            # '작성일'이나 '등록일' 문구가 없는 경우 건너뜀
            if "작성일" not in clean and "등록일" not in clean:
                continue
                
            # 현재 라벨 태그 다음에 오는 데이터 태그 탐색
            target = tag.find_next_sibling(["td", "dd", "div", "span"])
            if not target:
                # 형제 노드에 없을 경우 부모 노드(tr 등)를 기준으로 탐색 범위 확장
                parent = tag.find_parent(["tr", "th", "td", "dl"])
                if parent:
                    target = parent.find_next_sibling(["td", "dd"]) or (parent.find_next("td") if parent.name == "tr" else None)
            
            if target:
                # 데이터 태그에서 텍스트를 가져와 연도(4자리 숫자) 포함 여부 확인
                val = (target.get_text(strip=True) or "").strip()
                if val and re.search(r"\d{4}", val):
                    # 텍스트를 datetime 객체로 변환
                    dt = parse_date(val)
                    if dt:
                        return dt

        # 광명시 계약정보 대금지급 상세:
        # 상세 HTML에 계약일자가 있으면 등록일/기준일로 사용한다.
        if url and is_gm_contract_detail_url(url):
            try:
                gm_contract_dt = extract_gm_contract_reg_date_from_soup(soup, url=url)
                if gm_contract_dt:
                    return gm_contract_dt
            except Exception:
                pass
                        
        # Gwangmyeong Openworks bbs pages can hide registDt in the detail table.
        # q_bbscttSn is timestamp-like (YYYYMMDDHHMMSS...), so use it only as a late fallback.
        if url and "gm.go.kr" in (url or "").lower() and "q_bbscttSn=" in url:
            try:
                qs = parse_qs(urlparse(url).query)
                raw_sn = str((qs.get("q_bbscttSn") or [""])[0] or "").strip()
                if re.fullmatch(r"\d{14,}", raw_sn):
                    return datetime.strptime(raw_sn[:14], "%Y%m%d%H%M%S")
                if re.fullmatch(r"\d{8,}", raw_sn):
                    return datetime.strptime(raw_sn[:8], "%Y%m%d")
            except Exception:
                pass

        # 2) date_utils의 extract_post_date 폴백 (정규식/DT-DD)
        if html and BeautifulSoup:
            try:
                dt = extract_post_date(html, post_url=url or "")
                if dt:
                    return dt
            except Exception:
                pass

        # Final URL-only fallback: use reqYmd only when DOM/text registration-date extraction failed.
        try:
            dt = extract_req_ymd_date(url)
            if dt:
                return dt
        except Exception:
            pass
        return None

    # 본문 HTML에서 인라인 이미지(src/data-src 등)를 추출하여 URL 리스트로 반환
    def _extract_inline_image_urls(self, html: str, *, base_url: str) -> List[str]:
        if not html or not BeautifulSoup:
            return []
        try:
            soup = BeautifulSoup(html, "html.parser")  # type: ignore[arg-type]
        except Exception:
            return []
        urls: List[str] = []
        for tag in soup.find_all("img"):
            try:
                src = (
                    tag.get("src")
                    or tag.get("data-src")
                    or tag.get("data-original")
                    or tag.get("data-lazy")
                    or ""
                ).strip()
            except Exception:
                src = ""
            if not src:
                continue
            if src.lower().startswith("data:image/"):
                urls.append(src)
                continue
            try:
                full = urljoin(base_url, src)
            except Exception:
                full = src
            if full:
                urls.append(full)
        # dedupe (order preserve)
        seen = set()
        out: List[str] = []
        for u in urls:
            if u in seen:
                continue
            seen.add(u)
            out.append(u)
        return out

    # 본문 HTML에서 첨부 파일(링크) 후보를 추출하여 {href,name} 딕셔너리 리스트로 반환
    def _extract_attachment_links_generic(self, html: str, *, base_url: str) -> List[Dict[str, str]]:
        # HTML 데이터나 라이브러리가 없으면 즉시 종료
        if not html or not BeautifulSoup:
            return []
        try:
            # HTML 파싱 시도
            soup = BeautifulSoup(html, "html.parser")
        except Exception:
            return []

        # 감지할 파일 확장자 목록
        file_exts = (".pdf", ".hwp", ".hwpx", ".xls", ".xlsx", ".ppt", ".pptx")
        # 다운로드 핸들러 URL 패턴(확장자가 URL에 없는 경우에도 첨부로 인정)
        url_file_hints = ("downloadbbsfile", "atchmnflno", "filedown", "filedownload", "download", "atchfile", "atchfileid", "filedown.do", "download.do")
        urls: List[Dict[str, str]] = []
        seen = set()
        generic_download_labels = {
            "다운받기",
            "다운로드",
            "파일다운로드",
            "파일 다운받기",
            "바로보기",
            "미리보기",
            "pdf 다운받기",
            "pdf 다운로드",
            "hwp 다운받기",
            "hwp 다운로드",
            "hwpx 다운받기",
            "hwpx 다운로드",
            "xls 다운받기",
            "xlsx 다운받기",
            "ppt 다운받기",
            "pptx 다운받기",
            "doc 다운받기",
            "docx 다운받기",
            "csv 다운받기",
            "zip 다운받기",
        }

        def _infer_download_ext(*values: str) -> str:
            blob = " ".join(str(v or "") for v in values).lower()
            for ext in file_exts:
                if ext in blob:
                    return ext
            token_map = {
                "pdf": ".pdf",
                "hwp": ".hwp",
                "hwpx": ".hwpx",
                "xls": ".xls",
                "xlsx": ".xlsx",
                "ppt": ".ppt",
                "pptx": ".pptx",
                "doc": ".doc",
                "docx": ".docx",
                "csv": ".csv",
                "zip": ".zip",
            }
            for token, ext in token_map.items():
                if re.search(rf"\b{re.escape(token)}\b", blob):
                    return ext
            return ""

        def _is_generic_download_label(text: str) -> bool:
            norm = re.sub(r"\s+", " ", str(text or "").strip().lower())
            return bool(norm) and norm in generic_download_labels

        def _contextual_title_from_container(tag: Any, link_text: str, title_attr: str) -> str:
            remove_tokens = [token for token in (link_text, title_attr) if token]
            selectors = (
                "a[href*='view.do']",
                "a[href*='detail.do']",
                "a[href*='read.do']",
                "a.img",
                ".subject a",
                ".title a",
                "[class*='subject'] a",
                "[class*='title'] a",
                ".subject",
                ".title",
                "[class*='subject']",
                "[class*='title']",
            )
            try:
                containers = list(getattr(tag, "parents", []) or [])[:8]
            except Exception:
                containers = []
            for container in containers:
                if str(getattr(container, "name", "") or "").lower() not in {"li", "div", "tr", "td", "dl", "p"}:
                    continue
                for selector in selectors:
                    try:
                        candidates = container.select(selector)
                    except Exception:
                        candidates = []
                    for candidate in candidates:
                        try:
                            ctx = re.sub(r"\s+", " ", (candidate.get_text(" ", strip=True) or "").strip())
                        except Exception:
                            ctx = ""
                        for token in remove_tokens:
                            ctx = ctx.replace(token, " ")
                        ctx = re.sub(r"\s+", " ", ctx).strip(" -|:")
                        if ctx and not _is_generic_download_label(ctx) and len(ctx) <= 180:
                            return ctx
            return ""

        def _promote_contextual_name(tag: Any, current_name: str, link_text: str, title_attr: str, href: str) -> str:
            if not _is_generic_download_label(current_name):
                return current_name
            ctx = _contextual_title_from_container(tag, link_text, title_attr)
            if not ctx:
                try:
                    parents = list(getattr(tag, "parents", []) or [])[:4]
                except Exception:
                    parents = []
                for parent in parents:
                    try:
                        ctx = re.sub(r"\s+", " ", (parent.get_text(" ", strip=True) or "").strip())
                    except Exception:
                        ctx = ""
                    for token in (link_text, title_attr):
                        if token:
                            ctx = ctx.replace(token, " ")
                    ctx = re.sub(
                        r"(?i)\b(?:pdf|hwp|hwpx|xls|xlsx|ppt|pptx|doc|docx|csv|zip)\s*(?:다운받기|다운로드|파일다운로드|바로보기|미리보기)\b",
                        " ",
                        ctx,
                    )
                    ctx = re.sub(r"(?i)\b(?:다운받기|다운로드|파일다운로드|바로보기|미리보기|첨부파일)\b", " ", ctx)
                    ctx = re.sub(r"\s+", " ", ctx).strip(" -|:")
                    if ctx and ctx != current_name and len(ctx) <= 180:
                        break
            if not ctx or ctx == current_name or len(ctx) > 180:
                return current_name
            ext = _infer_download_ext(link_text, title_attr, href)
            if ext and not ctx.lower().endswith(ext):
                return f"{ctx}{ext}"
            return ctx
        for a in soup.find_all("a"):
            href = ""
            try:
                # 다양한 속성에서 링크 주소 추출 시도
                href = normalize_attachment_href(
                    (a.get("href") or a.get("data-href") or a.get("data-url") or "").strip()
                )
            except Exception:
                href = ""

            onclick = ""
            try:
                onclick = (a.get("onclick") or "").strip()
            except Exception:
                onclick = ""
            if onclick and (
                not href
                or href.startswith("#")
                or href.lower() in {"javascript:;", "javascript:void(0)", "javascript:void(0);"}
            ):
                try:
                    resolved = extract_download_url_from_js(onclick, base_url) or ""
                except Exception:
                    resolved = ""
                if not resolved:
                    resolved = resolve_anseong_yhlib_download_url(onclick, base_url) or ""
                if resolved:
                    href = normalize_attachment_href(resolved)

            if not href or href.startswith("#"):
                continue

            # [판단용 데이터 준비] 타이틀·링크 텍스트 (광진구청 등: 파일명 + '바로보기/바로듣기' 행은 뷰어·TTS용으로 실제 첨부 다운로드와 별개)
            title_attr = (a.get("title") or "").strip()
            link_text = (a.get_text(" ", strip=True) or "").strip()
            if "바로보기" in link_text or "바로듣기" in link_text:
                continue
            if "바로보기" in title_attr or "바로듣기" in title_attr:
                continue
            if title_attr and is_anseong_file_url(base_url):
                name = clean_anseong_attachment_name(title_attr) or title_attr
            else:
                name = (title_attr or link_text or "").strip()
            lname = name.lower()
            lhref = href.lower()

            # [수정] 자바스크립트 링크 처리: 다운로드 함수이거나 이름에 확장자가 있으면 허용
            is_js = lhref.startswith("javascript:")
            if is_js:
                # 함수 이름에 download가 있거나 파일명 텍스트에 확장자가 있는 경우만 통과
                is_download_call = any(k in lhref for k in ("download", "filedown")) or \
                                any(lname.endswith(ext) for ext in file_exts) or any(ext in lname for ext in file_exts)
                if not is_download_call:
                    continue

            # [수정] 절대 경로 생성: 자바스크립트가 아닐 때만 도메인을 결합
            try:
                full = href if is_js else urljoin(base_url, href)
            except Exception:
                full = href
            
            if not full:
                continue

            lfull = full.lower()
            # URL이 다운로드 핸들러 형태인지(예: downloadBbsFile.do?atchmnflNo=...)
            is_download_handler = any(hint in lfull for hint in url_file_hints)
            # 파일 판정: URL에 확장자 포함 / 링크 텍스트가 확장자로 끝남 / 링크 텍스트에 확장자 포함(예: "xxx.pdf 파일다운로드") / 다운로드 핸들러+이름에 확장자
            has_ext = (
                any(ext in lfull for ext in file_exts)
                or any(lname.endswith(ext) for ext in file_exts)
                or any(ext in lname for ext in file_exts)
                or (is_download_handler and any(ext in lname for ext in file_exts))
                or (is_download_handler and bool(_infer_download_ext(name, title_attr, link_text)))
            )
            if not has_ext:
                continue

            # 이름이 없는 경우 URL 마지막 경로에서 파일명 추출 시도
            if not name:
                try:
                    name = (urlparse(full).path or "").rsplit("/", 1)[-1]
                except Exception:
                    name = ""
            name = _promote_contextual_name(a, name, link_text, title_attr, href)
            if not name:
                name = "attachment"

            # 기능별 1줄 주석설명: JavaScript 링크인 경우 파일명을 조합하여 고유 키를 생성함으로써 중복 누락 방지
            if full.lower().startswith("javascript:"):
                # JS 링크는 파일명을 포함하여 고유성 확보 (구로구청 등 공공기관 대응)
                key = f"{full}_{name}"
            else:
                # 일반 URL은 기존 정규화 방식 유지
                key = canonicalize_url_for_dedup(full) or full

            # 기능별 1줄 주석설명: 생성된 고유 키가 처음 발견된 경우에만 수집 리스트에 추가
            if key not in seen:
                seen.add(key)
                urls.append({"href": full, "name": name})

        if is_anseong_file_url(base_url) and not urls:
            for img in soup.find_all("img"):
                try:
                    src = normalize_attachment_href((img.get("src") or "").strip())
                except Exception:
                    src = ""
                if not src:
                    continue
                try:
                    full = urljoin(base_url, src)
                except Exception:
                    full = src
                lfull = (full or "").lower()
                if "/common/file/img/view.do" not in lfull:
                    continue
                if "atchfileid=" not in lfull or "filesn=" not in lfull:
                    continue
                try:
                    name = (
                        (img.get("alt") or "")
                        or (img.get("title") or "")
                        or "inline_image"
                    ).strip()
                except Exception:
                    name = "inline_image"
                name = re.sub(r"\s+", " ", name).strip()[:180] or "inline_image"
                if not re.search(r"\.(?:jpg|jpeg|png|gif|bmp|webp)$", name, re.IGNORECASE):
                    name = f"{name}.jpg"
                key = canonicalize_url_for_dedup(full) or full
                if key not in seen:
                    seen.add(key)
                    urls.append({"href": full, "name": name})
                
        return urls
        
    async def _ocr_inline_images(self, *, img_urls: List[str], base_url: str) -> str:
        if not img_urls:
            return ""
        try:
            max_images = int(os.getenv("BOARD_CONTENT_INLINE_IMAGE_OCR_MAX", "3") or "3")
        except Exception:
            max_images = 3
        max_images = max(1, min(max_images, 10))
        try:
            max_bytes = int(os.getenv("BOARD_CONTENT_INLINE_IMAGE_OCR_MAX_BYTES", "5000000") or "5000000")
        except Exception:
            max_bytes = 5_000_000
        max_bytes = max(100_000, min(max_bytes, 20_000_000))
        try:
            timeout_sec = float(os.getenv("BOARD_CONTENT_INLINE_IMAGE_OCR_TIMEOUT_SEC", "8") or "8")
        except Exception:
            timeout_sec = 8.0
        timeout_sec = max(2.0, min(timeout_sec, 30.0))

        try:
            from edu.img_edu import extract_text_from_image  # type: ignore
        except Exception as imp_exc:
            logger.warning("[BoardContent] inline image OCR dependency missing: %s", imp_exc)
            return ""

        out_texts: List[str] = []
        tmp_root = os.path.join(self.downloads_dir, "inline_images", str(self.job_id or "default"))
        try:
            os.makedirs(tmp_root, exist_ok=True)
        except Exception:
            pass

        session = await self._get_http_session(timeout_sec=timeout_sec)
        for src in img_urls[:max_images]:
            file_path = ""
            try:
                data: Optional[bytes] = None
                ext = ".img"
                if src.lower().startswith("data:image/"):
                    try:
                        header, b64 = src.split(",", 1)
                        mime = header.split(";")[0].split(":", 1)[-1]
                        if "svg" in mime:
                            continue
                        if "/" in mime:
                            ext = "." + mime.split("/")[-1].split("+")[0]
                        data = base64.b64decode(b64)
                    except Exception:
                        data = None
                else:
                    if session is None:
                        continue
                    try:
                        async with self._guarded_session_get(
                            session,
                            src,
                            channel="asset",
                            allow_redirects=True,
                            timeout=aiohttp.ClientTimeout(total=timeout_sec),
                        ) as resp:
                            if resp.status != 200:
                                continue
                            data = await resp.read()
                    except Exception:
                        data = None
                if not data:
                    continue
                if len(data) > max_bytes:
                    continue
                file_name = f"inline_{uuid.uuid4().hex}{ext}"
                file_path = os.path.join(tmp_root, file_name)
                try:
                    with open(file_path, "wb") as f:
                        f.write(data)
                except Exception:
                    file_path = ""
                if not file_path:
                    continue
                try:
                    ocr_text = await extract_text_from_image(file_path)
                except Exception:
                    ocr_text = ""
                if ocr_text:
                    out_texts.append(str(ocr_text).strip())
            finally:
                if file_path:
                    try:
                        os.remove(file_path)
                    except Exception:
                        pass
        return "\n".join([t for t in out_texts if t]).strip()

    async def _maybe_learn_selector_profiles(self, detail_items: List[_DetailItem]) -> None:
        """
        도메인별로 샘플 N개를 분석하여 최적의 셀렉터를 학습하고 저장합니다.
        """
        if not self.enable_selector_learning:
            return

        # 1. 학습 대상 도메인 및 게시판 그룹화 (Bucketing)
        buckets: Dict[str, Dict[str, Any]] = {}
        stats = {"cached": 0, "no_dom": 0}

        for item in detail_items:
            try:
                domain = urlparse(item.url).netloc.lower()
                if not domain: raise ValueError
                
                board_url = getattr(item, "board_url", "") or ""
                profile_key = make_profile_key(domain, board_url)
                
                if profile_key in self._selector_profile_cache:
                    stats["cached"] += 1
                    continue

                if profile_key not in buckets:
                    buckets[profile_key] = {"domain": domain, "board_url": board_url, "urls": []}
                
                if len(buckets[profile_key]["urls"]) < self.selector_learning_samples:
                    buckets[profile_key]["urls"].append(item.url)
            except Exception:
                stats["no_dom"] += 1

        # 설정된 최소 샘플 수(기본 2개)를 충족하는 버킷만 필터링
        min_need = max(1, int(getattr(self, "selector_learning_samples", 2)))
        buckets = {k: v for k, v in buckets.items() if len(v["urls"]) >= min_need}

        if not buckets:
            return

        # 2. 학습 시작 로그 및 동시성 설정
        t0 = time.monotonic()
        logger.info(f"[SelectorLearning] Start | Targets: {len(buckets)}, Samples: {min_need}, JobID: {self.job_id}")
        
        default_selector_conc = int(getattr(settings, "BOARD_SELECTOR_LEARNING_CONCURRENCY", 3) or 3)
        concurrency = max(1, min(int(default_selector_conc), 128))
        semaphore = asyncio.Semaphore(concurrency)

        # 3. 내부 헬퍼 함수: 셀렉터 사후 검증 및 정제
        def _validate_selectors(inferred: Dict, html: str) -> Dict:
            try:
                from bs4 import BeautifulSoup
                soup = BeautifulSoup(html, "html.parser")
            except Exception:
                return inferred

            cleaned = dict(inferred)
            
            # 제목 검증 (breadcrumb 노이즈 및 너무 짧은 텍스트 필터링)
            if (sel := cleaned.get("title_selector")):
                el = soup.select_one(str(sel))
                txt = el.get_text(strip=True) if el else ""
                if not txt or any(x in txt for x in ["HOME", ">", "공유", "프린트"]) or len(txt) < 4:
                    cleaned["title_selector"] = None

            # 본문 검증 (비정상적인 길이 및 wrapper 노이즈 필터링)
            if (sel := cleaned.get("content_selector")):
                el = soup.select_one(str(sel))
                txt = el.get_text(strip=True) if el else ""
                if len(txt) < 50 or (">" in txt and "HOME" in txt):
                    cleaned["content_selector"] = None

            # 조회수 검증 (숫자 형식 여부 확인)
            if (sel := cleaned.get("view_selector")):
                el = soup.select_one(str(sel))
                txt = re.sub(r'[, ]', '', el.get_text(strip=True)) if el else ""
                if not (txt.isdigit() and len(txt) <= 12):
                    cleaned["view_selector"] = None

            return cleaned

        # 4. 도메인별 개별 학습 로직
        async def _learn_one_domain(profile_key: str, data: Dict) -> None:
            async with semaphore:
                # 기존 프로필 존재 여부 최종 확인
                existing = await get_profile(profile_key)
                if existing and (existing.get("content_selector") or existing.get("title_selector")):
                    self._selector_profile_cache[profile_key] = existing
                    return

                samples = []
                first_html = None
                
                for url in data["urls"]:
                    html = await self._fetch_html_static(url, timeout_sec=5.0)
                    if not html: continue
                    
                    if first_html is None: first_html = html
                    
                    candidates = build_minimal_candidates_from_html(html, max_candidates=8)
                    hints = build_page_hints_from_html(html)
                    if candidates:
                        samples.append({"url": url, "candidates": candidates, "page_hints": hints})

                if not samples: return

                # LLM 추론 호출
                inferred = await infer_selectors_openai(
                    domain=data["domain"],
                    samples=samples,
                    model="gpt-4o-mini",
                    db_name=(str(self.db_name).strip() if getattr(self, "db_name", None) else None),
                )
                if not inferred: return

                # 결과 검증 및 프로필 생성
                inferred = _validate_selectors(inferred, first_html)
                
                profile = new_profile(
                    profile_key=profile_key,
                    domain=data["domain"],
                    board_url=data["board_url"],
                    model="gpt-4o-mini",
                    title_selector=inferred.get("title_selector"),
                    content_selector=inferred.get("content_selector"),
                    attachment_selector=inferred.get("attachment_selector"),
                    view_selector=inferred.get("view_selector"),
                    confidence=float(inferred.get("confidence") or 0.0),
                    samples=len(samples)
                )
                
                await upsert_profile(profile)
                self._selector_profile_cache[profile_key] = profile.to_dict()
                logger.info(f"[SelectorLearning] Done | Key: {profile_key}, Title: {profile.title_selector}")

        # 5. 모든 학습 태스크 실행 및 완료 대기
        tasks = [asyncio.create_task(_learn_one_domain(k, v)) for k, v in buckets.items()]
        if tasks:
            await asyncio.gather(*tasks, return_exceptions=True)
            
        duration = int((time.monotonic() - t0) * 1000)
        logger.info(f"[SelectorLearning] Finish | Targets: {len(buckets)}, Time: {duration}ms")

    async def _fetch_html_playwright_detail_fallback(
        self,
        url: str,
        *,
        allow_yongin: bool = False,
        list_url: str = "",
    ) -> Optional[str]:
        """
        전역 상세 폴백 전용: 동시 Playwright context 수를 세마포어로 제한하고 요청 간 랜덤 지연을 둔다.
        정적 1회 → 본 메서드 1회만 호출해 무한 루프를 막는다.
        """
        if not url:
            return None
        try:
            dmin = float(os.getenv("BOARD_CONTENT_DETAIL_PW_FALLBACK_DELAY_MIN", "0.35") or "0.35")
            dmax = float(os.getenv("BOARD_CONTENT_DETAIL_PW_FALLBACK_DELAY_MAX", "1.25") or "1.25")
        except Exception:
            dmin, dmax = 0.35, 1.25
        if dmax < dmin:
            dmin, dmax = dmax, dmin
        sem = getattr(self, "_detail_pw_fallback_sem", None)
        logger.info(
            "[FetchPlaywright][DetailFallback] start | job_id=%s allow_yongin=%s list_url=%s url=%s",
            getattr(self, "job_id", ""),
            allow_yongin,
            (list_url or "")[:180],
            (url or "")[:180],
        )
        async def _fetch_with_optional_click() -> Optional[str]:
            if allow_yongin and list_url:
                try:
                    click_url = url
                    click_list_url = list_url
                    click_url = self._https_to_http_fallback_url(click_url) or click_url
                    click_list_url = self._https_to_http_fallback_url(click_list_url) or click_list_url
                    html, _final_url = await render_page_via_playwright_click_from(
                        click_list_url,
                        click_url,
                        wait_until="domcontentloaded",
                        list_wait_ms=1000,
                        detail_wait_ms=int(float(os.getenv("BOARD_DETAIL_SLOW_BACKGROUND_DETAIL_WAIT_MS", "2500") or "2500")),
                    )
                    if html and len(html.strip()) > 80:
                        return self._remember_html_fetch_cache("playwright", url, html)
                    self._write_detail_failure_log(
                        "background_click_from_empty",
                        url=url,
                        board_url=click_list_url,
                        reason="click_from_empty_or_short_html",
                        html_len=len(html or ""),
                    )
                except Exception as exc:
                    self._write_detail_failure_log(
                        "background_click_from_fail",
                        url=url,
                        board_url=click_list_url if "click_list_url" in locals() else list_url,
                        reason="click_from_exception",
                        error=repr(exc),
                    )
                    logger.debug(
                        "[DetailSlowBackground] click_from failed | url=%s list_url=%s err=%s",
                        (url or "")[:160],
                        (list_url or "")[:160],
                        exc,
                    )
            return await self._fetch_html_playwright(url, allow_yongin=allow_yongin)

        if sem is None:
            delay = random.uniform(dmin, dmax)
            logger.info(
                "[FetchPlaywright][DetailFallback] no_semaphore_delay | job_id=%s delay_ms=%s url=%s",
                getattr(self, "job_id", ""),
                int(delay * 1000),
                (url or "")[:180],
            )
            await asyncio.sleep(delay)
            html = await _fetch_with_optional_click()
            logger.info(
                "[FetchPlaywright][DetailFallback] done | job_id=%s html_len=%s url=%s",
                getattr(self, "job_id", ""),
                len(html or ""),
                (url or "")[:180],
            )
            return html
        async with sem:
            delay = random.uniform(dmin, dmax)
            logger.info(
                "[FetchPlaywright][DetailFallback] semaphore_acquired | job_id=%s delay_ms=%s url=%s",
                getattr(self, "job_id", ""),
                int(delay * 1000),
                (url or "")[:180],
            )
            await asyncio.sleep(delay)
            html = await _fetch_with_optional_click()
            logger.info(
                "[FetchPlaywright][DetailFallback] done | job_id=%s html_len=%s url=%s",
                getattr(self, "job_id", ""),
                len(html or ""),
                (url or "")[:180],
            )
            return html

    async def _render_page_via_job_playwright(
        self,
        target_url: str,
        *,
        headers: Optional[dict] = None,
        referer: str = "",
        wait_until: str = "domcontentloaded",
        extra_wait_ms: int = 0,
        wait_for_selector: Optional[str] = None,
        wait_for_selector_timeout_ms: Optional[int] = None,
    ) -> Tuple[str, str]:
        await self._ensure_playwright()
        browser = getattr(self, "_pw_browser", None)
        if browser is None:
            raise PlaywrightRenderError("job playwright browser is not available")

        context = None
        try:
            context = await browser.new_context(
                ignore_https_errors=True,
                viewport={"width": 1920, "height": 1080},
                extra_http_headers=dict(headers or {}),
            )
            await configure_context_for_crawl(context, target_url)
            page = await context.new_page()
            await apply_stealth_if_needed(page, target_url)
            await page.goto(
                target_url,
                wait_until=wait_until,
                timeout=_board_playwright_page_timeout_ms(),
                referer=referer or "",
            )
            if extra_wait_ms:
                await page.wait_for_timeout(extra_wait_ms)
            if wait_for_selector:
                try:
                    await page.wait_for_selector(
                        wait_for_selector,
                        state="visible",
                        timeout=wait_for_selector_timeout_ms or min(_board_playwright_page_timeout_ms(), 8000),
                    )
                except Exception:
                    pass
            return await page.content(), page.url
        finally:
            if context is not None:
                try:
                    await context.close()
                except Exception:
                    pass
        
    async def _fetch_html_playwright(
        self,
        url: str,
        *,
        allow_yongin: bool = False,
        http_fallback_attempted: bool = False,
    ) -> Optional[str]:
        if not url:
            return None
        import asyncio

        url = self._normalize_board_url(url, preserve_query=True)
        original_url_for_http_fallback = url
        if _is_yongin_cityhall_url(url) and url.lower().startswith("https://"):
            url = "http://" + url[len("https://") :]
        cached_html = self._get_html_fetch_cache("playwright", url)
        if cached_html:
            logger.info(
                "[FetchPlaywright] cache_hit | job_id=%s html_len=%s url=%s",
                getattr(self, "job_id", ""),
                len(cached_html or ""),
                (url or "")[:180],
            )
            return cached_html
        logger.info(
            "[FetchPlaywright] start | job_id=%s allow_yongin=%s http_fallback_attempted=%s url=%s",
            getattr(self, "job_id", ""),
            allow_yongin,
            http_fallback_attempted,
            (url or "")[:180],
        )

        if _is_yongin_general_bbs_static_url(url) and not allow_yongin:
            logger.info(
                "[FetchPlaywright][blocked][YonginStaticOnly] url=%s",
                (url or "")[:160],
            )
            return None

        if is_edu_ingang_url(url):
            h = await self._fetch_edu_ingang_html(url)
            if h:
                return h

        if is_gangnamingang_han_url(url):
            h = await self._fetch_gangnamingang_html(url)
            if h:
                return h

        # 춘천 계약 상세: chuncheon_contract.fetch_contract_detail_html (포털→목록→상세·클릭 폴백)
        if _is_chuncheon_contract_detail_url(url):
            html = await _fetch_chuncheon_contract_html_playwright(url)
            if html:
                return html
            logger.warning("[Chuncheon] 계약 상세 HTML 미수집 | url=%s", (url or "")[:160])
            return None

        _extra_ms = 400
        _wait_selector = None
        if url and "museum.seoul.go.kr" in url.lower():
            _extra_ms = 1500
            _wait_selector = "#contents, article#content"

        for _attempt in range(2):
            try:
                logger.info(
                    "[FetchPlaywright] render_attempt_start | job_id=%s attempt=%s wait_until=%s extra_wait_ms=%s selector=%s url=%s",
                    getattr(self, "job_id", ""),
                    _attempt + 1,
                    "domcontentloaded",
                    _extra_ms,
                    _wait_selector or "",
                    (url or "")[:180],
                )
                async with self._domain_fetch_guard(url, channel="playwright"):
                    html, final_url = await self._render_page_via_job_playwright(
                        url,
                        wait_until="domcontentloaded",
                        extra_wait_ms=_extra_ms,
                        wait_for_selector=_wait_selector,
                        wait_for_selector_timeout_ms=12000 if _wait_selector else None,
                    )
                html_len = len(html or "")
                stripped_len = len((html or "").strip())
                logger.info(
                    "[FetchPlaywright] render_attempt_done | job_id=%s attempt=%s html_len=%s stripped_len=%s final_url=%s url=%s",
                    getattr(self, "job_id", ""),
                    _attempt + 1,
                    html_len,
                    stripped_len,
                    (final_url or "")[:180],
                    (url or "")[:180],
                )
                if html and len(html.strip()) > 80:
                    logger.info(
                        "[FetchPlaywright] success | job_id=%s attempt=%s html_len=%s final_url=%s url=%s",
                        getattr(self, "job_id", ""),
                        _attempt + 1,
                        html_len,
                        (final_url or "")[:180],
                        (url or "")[:180],
                    )
                    return self._remember_html_fetch_cache("playwright", url, html)
                if url and "museum.seoul.go.kr" in url.lower() and _attempt == 1:
                    logger.warning(
                        "[Playwright][museum.seoul] HTML 짧음/비어 있음(2회 시도 후) | len=%s url=%s",
                        len(html or ""),
                        (url or "")[:160],
                    )
            except Exception as exc:
                fallback_url = self._https_to_http_fallback_url(original_url_for_http_fallback)
                if fallback_url and not http_fallback_attempted and self._fetch_error_suggests_http_fallback(exc):
                    logger.debug(
                        "[FetchPlaywright][HttpsToHttpFallback] exception -> retry http | url=%s fallback=%s err=%s",
                        (original_url_for_http_fallback or "")[:160],
                        (fallback_url or "")[:160],
                        exc,
                    )
                    self._write_detail_failure_log(
                        "playwright_https_to_http_fallback",
                        url=original_url_for_http_fallback,
                        fallback_url=fallback_url,
                        reason="exception",
                        error=repr(exc),
                    )
                    return await self._fetch_html_playwright(
                        fallback_url,
                        allow_yongin=allow_yongin,
                        http_fallback_attempted=True,
                    )
                if url and "museum.seoul.go.kr" in url.lower():
                    logger.warning(
                        "[Playwright][museum.seoul] 시도 %s 실패 | url=%s err=%s",
                        _attempt + 1,
                        (url or "")[:160],
                        exc,
                    )
                await asyncio.sleep(0.3)
        fallback_url = self._https_to_http_fallback_url(original_url_for_http_fallback)
        if fallback_url and not http_fallback_attempted:
            logger.debug(
                "[FetchPlaywright][HttpsToHttpFallback] empty -> retry http | url=%s fallback=%s",
                (original_url_for_http_fallback or "")[:160],
                (fallback_url or "")[:160],
            )
            self._write_detail_failure_log(
                "playwright_https_to_http_fallback",
                url=original_url_for_http_fallback,
                fallback_url=fallback_url,
                reason="empty_or_short_html",
            )
            return await self._fetch_html_playwright(
                fallback_url,
                allow_yongin=allow_yongin,
                http_fallback_attempted=True,
            )
        return None

    async def _ensure_playwright(self) -> None:
        """브라우저만 기동. 컨텍스트/쿠키는 URL 방문 시마다 새로 생성(에페메럴)합니다."""
        async with self._pw_lock:
            if self._pw_browser is not None and (
                not hasattr(self._pw_browser, "is_connected") or self._pw_browser.is_connected()
            ):
                return
            # 끊긴 Browser만 정리하고, Playwright 드라이버(self._pw)는 유지해 launch를 한 번만 시도한다.
            if self._pw_browser is not None:
                try:
                    await self._pw_browser.close()
                except Exception:
                    pass
                self._pw_browser = None
            try:
                if self._pw is None:
                    self._pw = await async_playwright().start()
                self._pw_browser = await self._pw.chromium.launch(
                    headless=True,
                    args=["--disable-gpu", "--no-sandbox", "--disable-dev-shm-usage"],
                    timeout=_board_playwright_page_timeout_ms(),
                )
                logger.info(
                    "[PlaywrightPool] browser started | job_id=%s pool_size=%s page_timeout_ms=%s",
                    getattr(self, "job_id", ""),
                    _board_playwright_pool_size(),
                    _board_playwright_page_timeout_ms(),
                )
            except Exception as e:
                logger.error("[Playwright] chromium.launch 실패: %s", e)
                self._pw_browser = None
                
    async def _close_playwright(self) -> None:
        async with self._pw_lock:
            try:
                if self._pw_context:
                    await self._pw_context.close()
            except Exception:
                pass
            try:
                if self._pw_browser:
                    await self._pw_browser.close()
            except Exception:
                pass
            try:
                if self._pw:
                    await self._pw.stop()
            except Exception:
                pass
            self._pw = None
            self._pw_browser = None
            self._pw_context = None
            logger.debug("[PlaywrightPool] browser closed | job_id=%s", getattr(self, "job_id", ""))

    def _clear_run_memory_ledgers(self, *, keep_post_save_ledgers: bool = False) -> None:
        set_attrs = (
            "_seen_scan", "_seen_collection", "_seen_save", "_seen_study", "_seen_filtered_detail",
            "_counted_collection_keys", "_counted_save_keys", "_counted_study_keys",
            "_db_dup_checked", "_db_dup_urls", "_slow_detail_background_seen",
            "_static_detail_retry_later_keys", "_shadow_summary_row_ids",
        )
        if keep_post_save_ledgers:
            set_attrs = tuple(
                attr for attr in set_attrs
                if attr not in {
                    "_seen_filtered_detail",
                    "_counted_collection_keys",
                    "_counted_save_keys",
                    "_counted_study_keys",
                }
            )
        for attr in set_attrs:
            value = getattr(self, attr, None)
            if isinstance(value, set):
                value.clear()

        dict_attrs = (
            "_job_result_records", "_html_fetch_cache", "_static_fetch_outcomes",
            "_static_prefetch_empty_counts", "_static_prefetch_empty_block_until",
            "_duplicate_shadow_html_cache", "_duplicate_shadow_html_inflight",
            "_duplicate_shadow_title_cache", "_duplicate_shadow_title_inflight",
            "_duplicate_shadow_author_fields_cache", "_duplicate_shadow_author_fields_inflight",
            "_category_rule_resolve_cache", "_domain_fetch_timeout_log_last",
            "_domain_fetch_timeout_log_suppressed", "_domain_fetch_profile_env_cache",
            "_edu_ingang_rewrite_warm_urls", "_invalid_detail_fetch_reasons",
            "_file_duplicate_subject_size_cache", "_file_duplicate_subject_size_locks",
        )
        for attr in dict_attrs:
            value = getattr(self, attr, None)
            if isinstance(value, dict):
                value.clear()

        for attr in ("_static_detail_retry_later", "_last_cookies"):
            value = getattr(self, attr, None)
            if isinstance(value, list):
                value.clear()

        seen_state = getattr(self, "_dedupe_seen_state", None)
        if isinstance(seen_state, dict):
            for key in ("raw_urls", "processed"):
                value = seen_state.get(key)
                if hasattr(value, "clear"):
                    value.clear()
            for key in ("by_id", "by_canon"):
                value = seen_state.get(key)
                if isinstance(value, dict):
                    value.clear()

        self._db_dup_context = None
        self._exploration_shadow_context = None
        self._static_prefetch_last_prune_at = 0.0

    def _reset_run_state(self) -> None:
        """새 크롤링 시작 전 호출: Set·통계·스트릭 초기화로 기간필터/중복선별이 매 실행마다 적용되도록 함."""
        try:
            self._clear_run_memory_ledgers()
            self._empty_page_streak = 0
            self._no_new_page_streak = 0
            self._out_of_range_page_streak = 0
            # 파일 선별 시 LEARN_LIST 중복 SQL 메타 캐시(작업마다 재계산)
            try:
                self._file_dup_sql_bundle_v = None
                self._file_dup_sql_bundle_resolved = False
            except Exception:
                pass
            self.stats.update({
                "scan_count": 0,
                "collection_count": 0,
                "save_count": 0,
                "save_done_count": 0,
                "save_success_count": 0,
                "save_failed_count": 0,
                "study_count": 0,
                "study_done_count": 0,
                "study_success_count": 0,
                "study_failed_count": 0,
                "study_skipped_count": 0,
            })
            try:
                self.stats.pop("study_issue_samples", None)
            except Exception:
                pass
            for _k in (
                "study_fail_reason",
                "study_fail_url",
                "study_fail_detail",
                "event",
                "message",
            ):
                try:
                    self.stats.pop(_k, None)
                except Exception:
                    pass
        except Exception as e:
            logger.warning("[게시글][board] _reset_run_state 실패: %s", e)

    async def _await_board_pipeline_tail_tasks(self) -> None:
        """start_workflow 종료 직전: 게시판 전용 백그라운드 Task가 남으면 workflow_completed보다 먼저 끝나게 대기."""
        if self.stop_event.is_set() and not getattr(self, "_auto_stop_as_completed", False):
            await self._cancel_post_save_queue(reason="tail_wait_stop")
            return
        try:
            wait_sec = float(os.getenv("WORKFLOW_BOARD_TAIL_WAIT_SEC", "600") or "600")
        except Exception:
            wait_sec = 600.0
        if getattr(self, "is_attachment_file_crawl_workflow", False):
            try:
                wait_sec = max(wait_sec, float(getattr(self, "_file_crawl_tail_wait_sec", 0) or 0))
            except Exception:
                pass
        wait_sec = max(0.0, min(wait_sec, 7200.0))
        if wait_sec <= 0:
            return
        try:
            q = getattr(self, "_post_save_queue", None)
            if isinstance(q, asyncio.Queue):
                qsize = q.qsize()
                if not getattr(self, "_post_save_wait_on_finalize", False):
                    if qsize > 0:
                        logger.info(
                            "[LearnListQueue] detached; finalize will not wait | job_id=%s qsize=%s workers=%s",
                            getattr(self, "job_id", ""),
                            qsize,
                            len(getattr(self, "_post_save_worker_tasks", set()) or set()),
                        )
                    q = None
                if q is None:
                    raise StopAsyncIteration
                if qsize > 0:
                    logger.warning(
                        "[LearnListQueue] waiting queue drain before finalize | job_id=%s wait_sec=%s qsize=%s",
                        getattr(self, "job_id", ""),
                        int(wait_sec),
                        qsize,
                    )
                await asyncio.wait_for(q.join(), timeout=wait_sec)
                if qsize > 0:
                    logger.info(
                        "[LearnListQueue] queue drained before finalize | job_id=%s",
                        getattr(self, "job_id", ""),
                    )
        except asyncio.TimeoutError:
            logger.warning(
                "[LearnListQueue] queue drain timeout; finalize continues | job_id=%s wait_sec=%s qsize=%s",
                getattr(self, "job_id", ""),
                int(wait_sec),
                getattr(getattr(self, "_post_save_queue", None), "qsize", lambda: -1)(),
            )
        except StopAsyncIteration:
            pass
        except Exception as exc:
            logger.warning(
                "[LearnListQueue] queue drain failed; finalize continues | job_id=%s err=%s",
                getattr(self, "job_id", ""),
                exc,
            )
        try:
            retry_q = getattr(self, "_slow_detail_retry_queue", None)
            retry_active = int(getattr(self, "_slow_detail_retry_active_jobs", 0) or 0)
            if isinstance(retry_q, asyncio.Queue) and (retry_q.qsize() > 0 or retry_active > 0):
                retry_qsize = retry_q.qsize()
                logger.warning(
                    "[DetailRetryQueue] waiting queue drain before finalize | job_id=%s wait_sec=%s qsize=%s active=%s",
                    getattr(self, "job_id", ""),
                    int(wait_sec),
                    retry_qsize,
                    retry_active,
                )
                self._write_detail_failure_log(
                    "detail_retry_queue_drain_start",
                    wait_sec=int(wait_sec),
                    retry_queue_size=retry_qsize,
                    retry_active=retry_active,
                )
                if getattr(self, "is_attachment_file_crawl_workflow", False):
                    try:
                        self.stats["file_detail_retry_queue_drain_started"] = True
                        self.stats["file_detail_retry_queue_drain_start_size"] = retry_qsize
                        self.stats["file_detail_retry_queue_drain_start_active"] = retry_active
                    except Exception:
                        pass
                await asyncio.wait_for(retry_q.join(), timeout=wait_sec)
                logger.info(
                    "[DetailRetryQueue] queue drained before finalize | job_id=%s",
                    getattr(self, "job_id", ""),
                )
                self._write_detail_failure_log(
                    "detail_retry_queue_drain_done",
                    wait_sec=int(wait_sec),
                    retry_queue_size=retry_q.qsize(),
                    retry_active=int(getattr(self, "_slow_detail_retry_active_jobs", 0) or 0),
                )
                if getattr(self, "is_attachment_file_crawl_workflow", False):
                    try:
                        self.stats["file_detail_retry_queue_drain_done"] = True
                        self.stats["file_detail_retry_queue_drain_timeout"] = False
                        self.stats["file_detail_retry_queue_drain_remaining"] = retry_q.qsize()
                    except Exception:
                        pass
        except asyncio.TimeoutError:
            retry_q = getattr(self, "_slow_detail_retry_queue", None)
            retry_qsize = getattr(retry_q, "qsize", lambda: -1)()
            retry_active = int(getattr(self, "_slow_detail_retry_active_jobs", 0) or 0)
            logger.warning(
                "[DetailRetryQueue] queue drain timeout; finalize continues | job_id=%s wait_sec=%s qsize=%s active=%s",
                getattr(self, "job_id", ""),
                int(wait_sec),
                retry_qsize,
                retry_active,
            )
            self._write_detail_failure_log(
                "detail_retry_queue_drain_timeout",
                wait_sec=int(wait_sec),
                retry_queue_size=retry_qsize,
                retry_active=retry_active,
            )
            if getattr(self, "is_attachment_file_crawl_workflow", False):
                try:
                    self.stats["file_detail_retry_queue_drain_done"] = False
                    self.stats["file_detail_retry_queue_drain_timeout"] = True
                    self.stats["file_detail_retry_queue_drain_remaining"] = retry_qsize
                    self.stats["file_detail_retry_queue_drain_remaining_active"] = retry_active
                except Exception:
                    pass
        except Exception as exc:
            logger.warning(
                "[DetailRetryQueue] queue drain failed; finalize continues | job_id=%s err=%s",
                getattr(self, "job_id", ""),
                exc,
            )
            self._write_detail_failure_log(
                "detail_retry_queue_drain_failed",
                wait_sec=int(wait_sec),
                error=repr(exc),
            )
        pending: List[asyncio.Task] = []
        for attr in ("_post_job_cate_update_task", "_selector_learning_task", "_discover_overflow_task"):
            t = getattr(self, attr, None)
            if isinstance(t, asyncio.Task) and not t.done():
                pending.append(t)
        try:
            meta = getattr(self, "_meta_extraction_tasks", None)
            if isinstance(meta, set):
                for t in list(meta):
                    if isinstance(t, asyncio.Task) and not t.done():
                        pending.append(t)
        except Exception:
            pass
        try:
            misc = getattr(self, "_background_misc_tasks", None)
            if isinstance(misc, set):
                label_map = getattr(self, "_background_misc_task_labels", {}) or {}
                for t in list(misc):
                    if isinstance(t, asyncio.Task) and not t.done():
                        try:
                            if str(label_map.get(t) or "") == "slow_detail_retry_worker":
                                continue
                        except Exception:
                            pass
                        pending.append(t)
        except Exception:
            pass
        if not pending:
            return
        pending_labels: List[str] = []
        try:
            label_map = getattr(self, "_background_misc_task_labels", {}) or {}
        except Exception:
            label_map = {}
        for task in pending:
            label = ""
            try:
                label = str(label_map.get(task) or "")
            except Exception:
                label = ""
            if not label:
                for attr in ("_post_job_cate_update_task", "_selector_learning_task", "_discover_overflow_task"):
                    if getattr(self, attr, None) is task:
                        label = attr
                        break
            pending_labels.append(label or getattr(task, "get_name", lambda: "task")())
        logger.warning(
            "[Workflow][TailWait] waiting background tasks before finalize | job_id=%s wait_sec=%s pending=%s labels=%s",
            getattr(self, "job_id", ""),
            int(wait_sec),
            len(pending),
            pending_labels[:20],
        )
        try:
            await asyncio.wait_for(asyncio.gather(*pending, return_exceptions=True), timeout=wait_sec)
        except asyncio.TimeoutError:
            still_pending = []
            for task, label in zip(pending, pending_labels):
                if isinstance(task, asyncio.Task) and not task.done():
                    still_pending.append(label)
            logger.warning(
                "[Workflow][TailWait] timeout; finalize continues | job_id=%s wait_sec=%s still_pending=%s labels=%s",
                getattr(self, "job_id", ""),
                int(wait_sec),
                len(still_pending),
                still_pending[:20],
            )
        except Exception as exc:
            logger.warning(
                "[Workflow][TailWait] wait failed; finalize continues | job_id=%s err=%s labels=%s",
                getattr(self, "job_id", ""),
                exc,
                pending_labels[:20],
            )

    async def _finalize_stats(self):
        """작업 종료 시 최종 통계 확정 및 SSE 콜백 전송"""
        await self._await_board_pipeline_tail_tasks()
        async with self._stats_lock:
            # 실시간으로 업데이트해왔지만, 마지막으로 세트 크기를 확인하여 동기화
            _scan_sync = getattr(self, "_sync_scan_count_before_finalize_snapshot", None)
            if _scan_sync is not None:
                _scan_sync()
            elif hasattr(self, "_seen_scan") and self._seen_scan:
                if not getattr(self, "_lock_scan_count_from_pre_explored", False):
                    self.stats["scan_count"] = len(self._seen_scan)
            # crawled_*.json 저장용: clear 전에 스냅샷 보관 (workflow_runner에서 사용)
            if hasattr(self, "_seen_scan") and self._seen_scan:
                self._crawled_urls_snapshot = list(self._seen_scan)
            else:
                self._crawled_urls_snapshot = []

            if getattr(self, "is_attachment_file_crawl_workflow", False):
                try:
                    self._sync_file_pipeline_counters_into_stats_dict()
                except Exception:
                    pass
                try:
                    target_posts = max(
                        int(self.stats.get("scan_detail_leg", 0) or 0),
                        int(self.stats.get("pre_explored_start_urls_count", 0) or 0),
                        int(self.stats.get("actual_start_urls_count", 0) or 0),
                        int(self.stats.get("selected_start_urls_count", 0) or 0),
                    )
                    start_urls_input = int(self.stats.get("file_start_urls_input_count", 0) or 0)
                    start_urls_enqueued = int(self.stats.get("file_start_urls_enqueued_count", 0) or 0)
                    start_urls_not_enqueued = int(self.stats.get("file_start_urls_not_enqueued_count", 0) or 0)
                    start_urls_scope_skipped = int(self.stats.get("file_start_urls_scope_skipped_count", 0) or 0)
                    fetch_success = int(self.stats.get("file_detail_fetch_success_count", 0) or 0)
                    detail_started = int(self.stats.get("file_detail_started_count", 0) or 0)
                    no_html = int(self.stats.get("file_detail_no_html_count", 0) or 0)
                    no_html_reasons = dict(self.stats.get("file_detail_no_html_reason_counts") or {})
                    no_html_samples = list(self.stats.get("file_detail_no_html_samples") or [])[:10]
                    invalid_fetch = int(self.stats.get("file_detail_invalid_fetch_count", 0) or 0)
                    background_queued = int(self.stats.get("file_detail_background_queued_count", 0) or 0)
                    background_final_empty = int(
                        self.stats.get("file_detail_no_html_background_final_empty_count", 0) or 0
                    )
                    retry_drain_timeout = bool(self.stats.get("file_detail_retry_queue_drain_timeout", False))
                    retry_drain_remaining = int(self.stats.get("file_detail_retry_queue_drain_remaining", 0) or 0)
                    retry_queue_last = int(self.stats.get("file_detail_background_retry_queue_size_last", 0) or 0)
                    extract_attempt = int(self.stats.get("file_attachment_extract_attempt_count", 0) or 0)
                    extract_empty = int(self.stats.get("file_attachment_extract_empty_count", 0) or 0)
                    found_posts = int(self.stats.get("file_attachment_found_post_count", 0) or 0)
                    found_total = int(self.stats.get("file_attachment_found_total_count", 0) or 0)
                    enqueue_input = int(self.stats.get("file_attachment_enqueue_input_total", 0) or 0)
                    enqueue_candidate = int(self.stats.get("file_attachment_enqueue_candidate_total", 0) or 0)
                    enqueue_enqueued = int(self.stats.get("file_attachment_enqueue_enqueued_total", 0) or 0)
                    enqueue_total_dropped = int(self.stats.get("file_attachment_enqueue_dropped_total", 0) or 0)
                    enqueue_duplicate_dropped = int(
                        self.stats.get("file_attachment_enqueue_duplicate_drop_total", 0) or 0
                    )
                    enqueue_candidate_skipped = max(0, enqueue_input - enqueue_candidate)
                    try:
                        enqueue_candidate_skip_reasons = dict(
                            self.stats.get("file_attachment_enqueue_candidate_skip_reason_counts") or {}
                        )
                    except Exception:
                        enqueue_candidate_skip_reasons = {}
                    enqueue_missing = max(0, enqueue_candidate - enqueue_enqueued - enqueue_duplicate_dropped)
                    enqueue_dropped = max(0, enqueue_total_dropped - enqueue_duplicate_dropped)
                    try:
                        enqueue_missing_reasons = dict(
                            self.stats.get("file_attachment_enqueue_missing_reason_counts") or {}
                        )
                    except Exception:
                        enqueue_missing_reasons = {}
                    enqueue_missing_samples = list(
                        self.stats.get("file_attachment_enqueue_missing_samples") or []
                    )[:10]
                    fetch_success_observed = max(
                        fetch_success,
                        int(self.stats.get("file_fast_front_success_count", 0) or 0),
                        extract_attempt,
                        found_posts,
                    )
                    save_failed = int(self.stats.get("save_failed_count", 0) or 0)
                    download_skipped = int(self.stats.get("file_download_skipped_count", 0) or 0)
                    save_success = int(self.stats.get("save_success_count", self.stats.get("save_count", 0)) or 0)
                    save_done = int(self.stats.get("save_done_count", 0) or 0)
                    study_failed = int(self.stats.get("file_study_failed_count", 0) or 0)
                    study_skipped = int(self.stats.get("file_study_skipped_count", 0) or 0)
                    download_unaccounted = max(0, enqueue_enqueued - save_done - download_skipped)
                    download_skip_reasons = {}
                    study_skip_reasons = {}
                    study_fail_reasons = {}
                    try:
                        for sample in list(self.stats.get("file_download_skipped_samples") or []):
                            if not isinstance(sample, dict):
                                continue
                            reason_s = str(sample.get("reason") or "unknown").strip() or "unknown"
                            download_skip_reasons[reason_s] = int(download_skip_reasons.get(reason_s, 0) or 0) + 1
                        records = getattr(self, "_job_result_records", None)
                        if isinstance(records, dict):
                            for record in records.values():
                                if not isinstance(record, dict):
                                    continue
                                if str(record.get("stage") or "").strip().lower() != "study":
                                    continue
                                status_s = str(record.get("status") or "").strip().lower()
                                reason_s = str(record.get("reason") or "unknown").strip() or "unknown"
                                if status_s == "skipped":
                                    study_skip_reasons[reason_s] = int(study_skip_reasons.get(reason_s, 0) or 0) + 1
                                elif status_s == "failed":
                                    study_fail_reasons[reason_s] = int(study_fail_reasons.get(reason_s, 0) or 0) + 1
                        if not study_skip_reasons:
                            last_skip_reason = str(self.stats.get("file_study_skip_reason") or "").strip()
                            if last_skip_reason:
                                study_skip_reasons[last_skip_reason] = study_skipped
                        if not study_fail_reasons:
                            last_fail_reason = str(self.stats.get("file_study_fail_reason") or "").strip()
                            if last_fail_reason:
                                study_fail_reasons[last_fail_reason] = study_failed
                    except Exception:
                        study_skip_reasons = {}
                        study_fail_reasons = {}
                    def _format_reason_counts(reason_counts):
                        reason_labels = {
                            "duplicate_reuse_learned": "기존 학습 파일 재사용",
                            "duplicate_learn_pipeline_skip": "중복 파일 학습 생략",
                            "duplicate_existing": "기존 파일 중복",
                            "file_pipeline_skip_learning": "학습 생략 옵션 적용",
                            "learning_blocked_by_rrn_pattern": "주민등록번호 패턴 감지",
                            "encrypted_hwpx": "암호화된 HWPX 파일",
                            "stop_requested": "사용자 중단 요청",
                            "download_failed": "파일 다운로드 실패",
                            "websync_failed": "웹서버 공개 URL 검증 실패",
                            "non_doc_file": "문서가 아닌 파일 제외",
                            "non_doc_precheck": "문서 파일 사전 검증 제외",
                            "non_doc_mime": "문서가 아닌 MIME 제외",
                            "empty_url": "파일 URL 없음",
                            "viewer_convert_url": "뷰어 변환 URL 제외",
                            "empty_extracted_text": "추출된 텍스트 없음",
                            "learning_pipeline_failed": "학습 파이프라인 실패",
                            "batch_embedding_submit_failed": "임베딩 배치 요청 실패",
                            "pg_table_missing": "학습 대상 테이블 없음",
                            "pg_runtime_missing": "학습 DB 연결 정보 없음",
                            "pg_learn_no_result": "학습 처리 결과 없음",
                            "post_save_learning_timeout": "저장 후 학습 시간 초과",
                            "learn_list_id_missing_after_learning": "학습 후 LEARN_LIST ID 없음",
                            "learning_pipeline_exception": "학습 파이프라인 예외",
                            "unknown": "원인 미확인",
                        }
                        try:
                            items = sorted(
                                (str(key or "unknown"), int(value or 0))
                                for key, value in dict(reason_counts or {}).items()
                                if int(value or 0) > 0
                            )
                        except Exception:
                            items = []
                        return (
                            ", ".join(
                                f"{reason_labels.get(key, key)}({value})"
                                for key, value in items
                            )
                            if items
                            else "없음(0)"
                        )
                    study_skip_reason_text = _format_reason_counts(study_skip_reasons)
                    study_fail_reason_text = _format_reason_counts(study_fail_reasons)
                    download_skip_reason_text = _format_reason_counts(download_skip_reasons)
                    enqueue_missing_labels = {
                        "file_meta_empty": "파일 정보 생성 실패",
                        "stop_requested": "사용자 중단 요청",
                        "unknown": "원인 미확인",
                    }
                    enqueue_candidate_skip_labels = {
                        "empty_url": "파일 URL 없음",
                        "seen_url": "동일 파일 URL이 이미 큐 등록됨",
                        "completed_cache": "최근 저장 완료 캐시",
                        "response_validation_failed": "파일 응답 검증 실패",
                        "scan_filter_non_doc": "비문서 확장자 필터",
                    }
                    try:
                        enqueue_candidate_skip_reason_text = ", ".join(
                            f"{enqueue_candidate_skip_labels.get(str(key or 'unknown'), str(key or 'unknown'))}({int(value or 0)})"
                            for key, value in sorted(dict(enqueue_candidate_skip_reasons or {}).items())
                            if int(value or 0) > 0
                        ) or "없음(0)"
                    except Exception:
                        enqueue_candidate_skip_reason_text = "원인 집계 실패"
                    try:
                        enqueue_missing_reason_text = ", ".join(
                            f"{enqueue_missing_labels.get(str(key or 'unknown'), str(key or 'unknown'))}({int(value or 0)})"
                            for key, value in sorted(dict(enqueue_missing_reasons or {}).items())
                            if int(value or 0) > 0
                        ) or "없음(0)"
                    except Exception:
                        enqueue_missing_reason_text = "원인 집계 실패"
                    study_skip_samples = list(self.stats.get("study_skip_samples") or [])[:10]
                    study_fail_samples = list(self.stats.get("study_issue_samples") or [])[:10]
                    self.stats["file_crawl_trust_summary"] = {
                        "target_posts": target_posts,
                        "start_urls_input": start_urls_input,
                        "start_urls_enqueued": start_urls_enqueued,
                        "start_urls_not_enqueued": start_urls_not_enqueued,
                        "start_urls_scope_skipped": start_urls_scope_skipped,
                        "detail_process_entered": detail_started,
                        "fetch_success": fetch_success_observed,
                        "fetch_failed_or_not_reached": max(0, target_posts - fetch_success_observed),
                        "detail_no_html": no_html,
                        "detail_no_html_reasons": no_html_reasons,
                        "detail_no_html_samples": no_html_samples,
                        "invalid_fetch": invalid_fetch,
                        "background_retry_queued": background_queued,
                        "background_final_empty": background_final_empty,
                        "retry_drain_timeout": retry_drain_timeout,
                        "retry_drain_remaining": retry_drain_remaining,
                        "retry_queue_size_last": retry_queue_last,
                        "extract_attempt": extract_attempt,
                        "extract_empty": extract_empty,
                        "attachment_found_posts": found_posts,
                        "attachment_found_total": found_total,
                        "enqueue_input": enqueue_input,
                        "enqueue_enqueued": enqueue_enqueued,
                        "enqueue_candidate": enqueue_candidate,
                        "enqueue_candidate_skipped": enqueue_candidate_skipped,
                        "enqueue_candidate_skip_reasons": enqueue_candidate_skip_reasons,
                        "enqueue_candidate_skip_reason_text": enqueue_candidate_skip_reason_text,
                        "enqueue_missing": enqueue_missing,
                        "enqueue_missing_reasons": enqueue_missing_reasons,
                        "enqueue_missing_reason_text": enqueue_missing_reason_text,
                        "enqueue_missing_samples": enqueue_missing_samples,
                        "enqueue_dropped": enqueue_dropped,
                        "enqueue_total_dropped": enqueue_total_dropped,
                        "enqueue_duplicate_dropped": enqueue_duplicate_dropped,
                        "download_skipped": download_skipped,
                        "download_skip_reasons": download_skip_reasons,
                        "download_skip_reason_text": download_skip_reason_text,
                        "save_success": save_success,
                        "save_done": save_done,
                        "download_unaccounted": download_unaccounted,
                        "save_failed": save_failed,
                        "file_study_failed": study_failed,
                        "file_study_skipped": study_skipped,
                        "file_study_skip_reasons": study_skip_reasons,
                        "file_study_fail_reasons": study_fail_reasons,
                        "file_study_skip_reason_text": study_skip_reason_text,
                        "file_study_fail_reason_text": study_fail_reason_text,
                        "file_study_skip_samples": study_skip_samples,
                        "file_study_fail_samples": study_fail_samples,
                    }
                    trust_summary_log_items = (
                        ("대상게시글", target_posts),
                        ("start_urls 입력", start_urls_input),
                        ("start_urls 큐투입", start_urls_enqueued),
                        ("start_urls 큐미투입", start_urls_not_enqueued),
                        ("스코프 제외", start_urls_scope_skipped),
                        ("상세처리진입 참고", detail_started),
                        ("fetch 성공", fetch_success_observed),
                        ("fetch 실패또는미도달 참고", max(0, target_posts - fetch_success_observed)),
                        ("상세 no_html", no_html),
                        ("invalid 상세", invalid_fetch),
                        ("background_retry 투입", background_queued),
                        ("background 최종 no_html", background_final_empty),
                        ("retry_drain_timeout", retry_drain_timeout),
                        ("retry 남은큐", retry_drain_remaining),
                        ("retry 큐마지막크기", retry_queue_last),
                        ("추출 시도", extract_attempt),
                        ("첨부 0개", extract_empty),
                        ("첨부 발견 게시글", found_posts),
                        ("발견 첨부 총수", found_total),
                        ("enqueue 입력첨부", enqueue_input),
                        ("enqueue 후보첨부", enqueue_candidate),
                        ("enqueue 성공", enqueue_enqueued),
                        ("enqueue 후보제외", enqueue_candidate_skipped),
                        ("enqueue 실제누락", enqueue_missing),
                        ("enqueue drop합계 참고", enqueue_dropped),
                        ("enqueue 중복제외", enqueue_duplicate_dropped),
                        ("다운로드 스킵", download_skipped),
                        ("저장 성공", save_success),
                        ("저장 완료처리", save_done),
                        ("큐투입 후 미정산", download_unaccounted),
                        ("저장 실패", save_failed),
                        ("파일학습 실패", study_failed),
                        ("파일학습 스킵", study_skipped),
                    )
                    for summary_index, (summary_label, summary_value) in enumerate(trust_summary_log_items):
                        if summary_index == 0:
                            logger.info(
                                "[FileCrawlTrustSummary] 신뢰도 요약: job_id=%s %s=%s",
                                self.job_id,
                                summary_label,
                                summary_value,
                            )
                        else:
                            logger.info(
                                "[FileCrawlTrustSummary] %s=%s",
                                summary_label,
                                summary_value,
                            )
                    logger.info(
                        "[FileCrawlTrustSummary] 파일크롤링 상세 no_html 원인분포 | job_id=%s no_html=%s reasons=%s samples=%s",
                        self.job_id,
                        no_html,
                        no_html_reasons,
                        no_html_samples,
                    )
                    logger.info(
                        "[FileCrawlTrustSummary] 큐등록 후보제외 원인분포 | job_id=%s skipped=%s reasons=%s",
                        self.job_id,
                        enqueue_candidate_skipped,
                        enqueue_candidate_skip_reason_text,
                    )
                    logger.info(
                        "[FileCrawlTrustSummary] 큐등록 실제누락 원인분포 | job_id=%s missing=%s reasons=%s samples=%s",
                        self.job_id,
                        enqueue_missing,
                        enqueue_missing_reason_text,
                        enqueue_missing_samples,
                    )
                    logger.info(
                        "[FileCrawlTrustSummary] 큐투입 처리정산 | job_id=%s enqueued=%s saved=%s save_done=%s skipped=%s unaccounted=%s",
                        self.job_id,
                        enqueue_enqueued,
                        save_success,
                        save_done,
                        download_skipped,
                        download_unaccounted,
                    )
                    logger.info(
                        "[FileCrawlTrustSummary] 다운로드 스킵 원인분포 | job_id=%s skipped=%s reasons=%s samples=%s",
                        self.job_id,
                        download_skipped,
                        download_skip_reason_text,
                        list(self.stats.get("file_download_skipped_samples") or [])[:10],
                    )
                    logger.info(
                        "[FileCrawlTrustSummary] 파일학습 스킵 원인분포 | job_id=%s skipped=%s reasons=%s samples=%s",
                        self.job_id,
                        study_skipped,
                        study_skip_reason_text,
                        study_skip_samples,
                    )
                    logger.info(
                        "[FileCrawlTrustSummary] 파일학습 실패 원인분포 | job_id=%s failed=%s reasons=%s samples=%s",
                        self.job_id,
                        study_failed,
                        study_fail_reason_text,
                        study_fail_samples,
                    )
                except Exception as summary_exc:
                    logger.warning(
                        "[FileCrawlTrustSummary] 파일크롤링 신뢰도 요약 생성 실패 | job_id=%s 오류=%s",
                        self.job_id,
                        summary_exc,
                    )
        
        # UI에 최종 결과값 반영을 위해 콜백 호출
        if hasattr(self, "progress_callback") and self.progress_callback:
            try:
                self.progress_callback(self.get_stats())
            except Exception as e:
                logger.warning(f"[Workflow] Final progress callback failed: {e}")

        # 다음 크롤링 작업 시 메모리 간섭을 방지하기 위해 모든 Set을 비웁니다.
        try:
            post_save_queue = getattr(self, "_post_save_queue", None)
            try:
                post_save_qsize = post_save_queue.qsize() if isinstance(post_save_queue, asyncio.Queue) else 0
            except Exception:
                post_save_qsize = 0
            try:
                post_save_active = int(getattr(self, "_post_save_active_jobs", 0) or 0)
            except Exception:
                post_save_active = 0
            detach_post_save = (
                getattr(self, "_post_save_async", False)
                and not getattr(self, "_post_save_wait_on_finalize", False)
                and not self.stop_event.is_set()
                and (post_save_qsize > 0 or post_save_active > 0)
            )
            self._clear_run_memory_ledgers(keep_post_save_ledgers=detach_post_save)
            if detach_post_save:
                logger.info(
                    "[LearnListQueue] kept running after workflow finalize | job_id=%s qsize=%s workers=%s",
                    getattr(self, "job_id", ""),
                    post_save_qsize,
                    len(getattr(self, "_post_save_worker_tasks", set()) or set()),
                )
            else:
                for task in list(getattr(self, "_post_save_worker_tasks", set()) or set()):
                    if isinstance(task, asyncio.Task) and not task.done():
                        task.cancel()
                self._post_save_worker_tasks.clear()
                self._post_save_queue = None
            
            # 필터링 연속 카운트 초기화
            self._empty_page_streak = 0
            self._no_new_page_streak = 0
            self._out_of_range_page_streak = 0
            self._db_dup_context = None
            
        except Exception as e:
            logger.warning(f"[Workflow] Memory cleanup failed: {e}")

    def _clean_data(self, data: Any) -> Any:
        """
        [범용 데이터 세척]
        문자열 내부의 Null Byte(\x00)를 제거합니다.
        딕셔너리나 리스트 구조일 경우 재귀적으로 탐색하여 세척합니다.
        """
        if isinstance(data, str):
            return data.replace('\x00', '')
        elif isinstance(data, dict):
            return {k: self._clean_data(v) for k, v in data.items()}
        elif isinstance(data, list):
            return [self._clean_data(i) for i in data]
        return data

    def _normalize_board_url(self, url: str, *, preserve_query: bool = False) -> str:
        """
        [정규화] 세션 식별자 및 가변 파라미터 제거하여 동일 게시물 여부를 판별합니다.
        비교용 키 생성용이며, DB 저장 시에는 사용하지 않습니다.
        - 공용: 페이지, 검색, 메뉴, 정렬 관련 불필요 파라미터 제거
        - 안성시청: 강좌 및 강사 페이지는 고유 ID 기반으로 URL 정규화
        """
        if not url:
            return url

        try:
            from urllib.parse import urlparse, parse_qsl, urlencode, urlunparse

            url = url.split(';')[0]  # 세션 식별자 제거
            parsed = urlparse(url)
            params = parse_qsl(parsed.query, keep_blank_values=True)
            host = parsed.netloc.lower()
            path = parsed.path
            params_dict = dict(params)

            if host == "museum.seoul.go.kr" and parsed.scheme.lower() == "http":
                parsed = parsed._replace(scheme="https")
                url = urlunparse((parsed.scheme, host, path, "", parsed.query, ""))

            if is_edu_ingang_url(url):
                normalized_edu_url = normalize_edu_ingang_detail_url(url)
                if normalized_edu_url != url:
                    warm_hint = derive_edu_ingang_warm_url(url)
                    if warm_hint:
                        self._edu_ingang_rewrite_warm_urls[normalized_edu_url] = warm_hint
                    url = normalized_edu_url
                    parsed = urlparse(url)
                    params = parse_qsl(parsed.query, keep_blank_values=True)
                    host = parsed.netloc.lower()
                    path = parsed.path
                    params_dict = dict(params)

            if "dongjak.go.kr" in host and "/yeyak/progrm/master/online/" in (path or ""):
                if not str(params_dict.get("tmplatSeCd") or "").strip():
                    tmplat_map = {
                        "1600012": "12",
                        "1600013": "13",
                        "1600014": "14",
                        "1600015": "15",
                        "1600016": "16",
                        "1600018": "21",
                        "1600045": "22",
                    }
                    menu_no = str(params_dict.get("menuNo") or "").strip()
                    tmplat_se_cd = tmplat_map.get(menu_no)
                    if tmplat_se_cd:
                        params.append(("tmplatSeCd", tmplat_se_cd))
                        params_dict["tmplatSeCd"] = tmplat_se_cd

            if preserve_query:
                return urlunparse((
                    parsed.scheme,
                    host,
                    path,
                    '',
                    urlencode(params, doseq=True),
                    ''
                ))

            # -------------------------
            # 안성시청 전용 분기
            # -------------------------
            if "anseong.go.kr" in host:
                # 강좌 상세 페이지
                if "eduLctreView.do" in path:
                    edu_no = params_dict.get("eduLctreNo")
                    inst_no = params_dict.get("eduInsttNo")
                    if edu_no and inst_no:
                        return f"{parsed.scheme}://{host}{path}?eduInsttNo={inst_no}&eduLctreNo={edu_no}"

                # 강사 상세 페이지
                if "selectInstrctrView.do" in path:
                    instrctr_no = params_dict.get("instrctrNo")
                    if instrctr_no:
                        return f"{parsed.scheme}://{host}{path}?instrctrNo={instrctr_no}"

            # -------------------------
            # 공용 정규화
            # -------------------------
            COMMON_EXCLUDE_PARAMS = {
                # 페이지
                'page','pageno','page_no','pageindex','pageunit','curpage','page_index',
                # 검색
                'searchcondition','searchkeyword','searchcnd','searchwrd',
                # 메뉴 / UI
                'mid','menuid','menu_id',
                # 정렬
                'sort','order','orderby'
            }

            # 제외 대상 + search* prefix 제거
            filtered = sorted([
                (k, v) for k, v in params
                if k.lower() not in COMMON_EXCLUDE_PARAMS
                and not k.lower().startswith("search")
            ])

            new_query = urlencode(filtered)

            return urlunparse((
                parsed.scheme,
                host,
                path,
                '',
                new_query,
                ''
            ))

        except Exception:
            return url
                 
    async def get_cookies(self):
        # 에페메럴 컨텍스트: 마지막 fetch 시 해당 컨텍스트에서 수집한 쿠키 반환
        if hasattr(self, '_pw_context') and self._pw_context:
            return await self._pw_context.cookies()
        return getattr(self, '_last_cookies', None) or []

    # [추가] 유입 경로(Referer)를 확인하기 위한 메서드
    async def get_referrer(self):
        """
        현재 Playwright 세션에 열려있는 페이지의 document.referrer를 가져옵니다.
        """
        try:
            # 브라우저 컨텍스트가 살아있는지 확인
            if hasattr(self, '_pw_context') and self._pw_context:
                pages = self._pw_context.pages
                if pages:
                    # 현재 활성화된 마지막 탭(페이지)에서 JS 실행
                    ref = await pages[-1].evaluate("document.referrer")
                    return ref if ref else "직접 접속 (Referrer 없음)"
        except Exception as e:
            logger.debug(f"[Referrer-Check] 오류: {e}")
            
        return "유입 경로 확인 불가"

    # 수정 후: API 호출 함수 추가
    async def _request_summarize_keywords(self, url: str) -> Optional[Dict[str, Any]]:
        """
        Dispatch summarize_keywords during normal board crawling.
        This call is part of the crawling/learning flow and does not depend on
        an opt-in environment variable.
        """
        from backend.shared.summarize_keywords_client import (
            enqueue_summarize_keywords,
            post_summarize_keywords,
            summarize_keywords_endpoint,
            summarize_keywords_payload_concurrency,
            summarize_keywords_timeout_sec,
            summarize_keywords_use_queue,
        )

        payload = {
            "chat_bot_id": str(self.chat_bot_id),
            "db_name": str(self.db_name),
            "contents": [url],
            "content_type": "url",
            "concurrency": summarize_keywords_payload_concurrency(),
        }

        try:
            if summarize_keywords_use_queue():
                await enqueue_summarize_keywords(
                    summarize_keywords_endpoint(),
                    payload,
                    timeout_sec=summarize_keywords_timeout_sec(),
                )
                logger.debug("[SummaryAPI] queued | url=%s", (url or "")[:160])
                return None
            status, body = await post_summarize_keywords(
                summarize_keywords_endpoint(),
                payload,
                timeout_sec=summarize_keywords_timeout_sec(),
            )
            if status != 200:
                logger.warning(
                    "[SummaryAPI] http=%s url=%s detail=%s",
                    status,
                    (url or "")[:160],
                    " ".join((body or "").split())[:240],
                )
                return None
            return json.loads(body)
        except Exception as e:
            logger.error(f"[SummaryAPI] 호출 실패: {e}") # 에러 로그 기록
        return None


